	/**
	 * Per diary area: the highest completed tier (null if none) and the number of tasks
	 * completed in each tier. Areas with neither are omitted. The tier stops at the first
	 * incomplete tier. Client thread only.
	 */
	private List<MyscapeClient.DiaryTierItem> readDiaryTiers()
	{
		List<MyscapeClient.DiaryTierItem> items = new ArrayList<>();
		for (Map.Entry<String, int[]> entry : DIARY_TIER_VARBITS.entrySet())
		{
			String area = entry.getKey();
			int[] tierVarbits = entry.getValue();
			int[] completeValues = DIARY_TIER_COMPLETE_VALUES.get(area);
			String highestTier = null;
			for (int i = 0; i < tierVarbits.length; i++)
			{
				if (client.getVarbitValue(tierVarbits[i]) < completeValues[i])
				{
					break;
				}
				highestTier = DIARY_TIER_NAMES[i];
			}
			int[] taskCounts = readDiaryTaskCounts(area);
			boolean anyTasks = false;
			for (int count : taskCounts)
			{
				anyTasks |= count > 0;
			}
			if (highestTier != null || anyTasks)
			{
				items.add(new MyscapeClient.DiaryTierItem(area, highestTier, taskCounts));
			}
		}
		return items;
	}

	/** Tasks completed per tier (easy to elite) for one diary area. Client thread only. */
	private int[] readDiaryTaskCounts(String area)
	{
		int index = -1;
		for (int i = 0; i < DIARY_TASK_COUNT_AREAS.length; i++)
		{
			if (DIARY_TASK_COUNT_AREAS[i].equals(area))
			{
				index = i;
				break;
			}
		}
		int[] counts = new int[DIARY_TIER_NAMES.length];
		if (index < 0)
		{
			return counts;
		}
		int packed = client.getVarpValue(DIARY_TASK_COUNT_FIRST_VARP + index / 2) >>> (16 * (index % 2));
		int[] widths = area.equals("karamja") ? DIARY_TASK_COUNT_WIDTHS_KARAMJA : DIARY_TASK_COUNT_WIDTHS_DEFAULT;
		for (int i = 0; i < counts.length; i++)
		{
			counts[i] = packed & ((1 << widths[i]) - 1);
			packed >>>= widths[i];
		}
		return counts;
	}

	// The Costume Room's contents (all furniture pieces) arrive on one container id.
	// It is assigned at runtime by the consolidated Costume Room interface script, so
	// there is no InventoryID constant for it.
	private static final int POH_COSTUME_ROOM_CONTAINER_ID = 33405;

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		ItemContainer container = event.getItemContainer();
		if (container == null)
		{
			return;
		}
		if (applyContainerSnapshot(event.getContainerId(), container))
		{
			scheduleSyncDebounced();
		}
	}

	/** Per-container dispatch, shared with the deferred re-read in onGameTick. Returns true if tracked. */
	private boolean applyContainerSnapshot(int containerId, ItemContainer container)
	{
		if (containerId == InventoryID.BANK)
		{
			latestBankItems = readBankItems(container);
			// A Rune Pouch can be banked, so ownership may have changed.
			runePouchDirty = true;
		}
		else if (containerId == InventoryID.INV)
		{
			latestInventoryItems = readInventoryItems(container);
			// Picking up or dropping a Rune Pouch changes ownership without any pouch
			// varbit changing, so re-read it on the next tick.
			runePouchDirty = true;
		}
		else if (containerId == InventoryID.WORN)
		{
			latestEquipmentItems = readEquipmentItems(container);
		}
		else if (containerId == InventoryID.LOOTING_BAG)
		{
			latestLootingBagItems = readLootingBagItems(container);
		}
		else if (containerId == InventoryID.SEED_VAULT)
		{
			latestSeedVaultItems = readSeedVaultItems(container);
		}
		else if (containerId == InventoryID.TACKLE_BOX)
		{
			latestTackleBoxItems = readTackleBoxItems(container);
		}
		else if (containerId == InventoryID.FORESTRY_KIT)
		{
			latestForestryKitItems = readForestryKitItems(container);
		}
		else if (containerId == InventoryID.SEED_BOX)
		{
			latestSeedBoxItems = readSeedBoxItems(container);
		}
		else if (containerId == InventoryID.HUNTSMANS_KIT)
		{
			latestHuntsmansKitItems = readHuntsmansKitItems(container);
		}
		else if (containerId == POH_COSTUME_ROOM_CONTAINER_ID)
		{
			latestPohItems = readPohItems(container);
		}
		else if (containerId == InventoryID.SAILING_BOAT_1_CARGOHOLD)
		{
			latestBoatCargo1Items = readBoatCargoItems(container);
		}
		else if (containerId == InventoryID.SAILING_BOAT_2_CARGOHOLD)
		{
			latestBoatCargo2Items = readBoatCargoItems(container);
		}
		else if (containerId == InventoryID.SAILING_BOAT_3_CARGOHOLD)
		{
			latestBoatCargo3Items = readBoatCargoItems(container);
		}
		else if (containerId == InventoryID.SAILING_BOAT_4_CARGOHOLD)
		{
			latestBoatCargo4Items = readBoatCargoItems(container);
		}
		else if (containerId == InventoryID.SAILING_BOAT_5_CARGOHOLD)
		{
			latestBoatCargo5Items = readBoatCargoItems(container);
		}
		else
		{
			// Not a container this plugin tracks.
			return false;
		}

		return true;
	}

	/**
	 * Handles loot published by RuneLite's Loot Tracker plugin, which must stay enabled.
	 * Each event is sent immediately (panel#syncLootInBackground), not debounced. The
	 * type is passed through by name so unknown types still sync. Clue caskets arrive as
	 * "Casket" with no tier, so the tier from the chat line (see pendingClueTier) is
	 * applied here. A combat level of -1 means none and is sent as null.
	 */
	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (panel == null)
		{
			return;
		}

		Map<Integer, Integer> quantities = new LinkedHashMap<>();
		for (ItemStack stack : event.getItems())
		{
			if (stack.getId() <= 0 || stack.getQuantity() <= 0)
			{
				continue;
			}
			quantities.merge(stack.getId(), stack.getQuantity(), Integer::sum);
		}
		if (quantities.isEmpty())
		{
			return;
		}

		List<MyscapeClient.LootEventItem> items = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : quantities.entrySet())
		{
			items.add(new MyscapeClient.LootEventItem(entry.getKey(), resolveItemName(entry.getKey()), entry.getValue()));
		}

		// A Casket event shortly after a clue completion line is that clue's reward.
		// The tier is cleared immediately so it cannot go stale.
		String sourceName = event.getName();
		if ("EVENT".equals(event.getType().name()) && CASKET_EVENT_NAME.equals(sourceName)
			&& pendingClueTier != null
			&& client.getTickCount() - pendingClueTierTick <= CLUE_TIER_MAX_TICK_GAP)
		{
			sourceName = "Clue Scroll (" + pendingClueTier + ")";
		}
		pendingClueTier = null;

		Integer combatLevel = event.getCombatLevel() >= 0 ? event.getCombatLevel() : null;
		MyscapeClient.LootEvent lootEvent = new MyscapeClient.LootEvent(
			UUID.randomUUID().toString(),
			sourceName,
			event.getType().name().toLowerCase(),
			combatLevel,
			Instant.now().toString(),
			items
		);
		panel.syncLootInBackground(lootEvent);
	}

	// Tier (e.g. "Hard") from the "You have completed N <tier> Treasure Trails." chat
	// line, waiting for the matching Casket loot event (the chat line has no items).
	private volatile String pendingClueTier;

	// Tick on which pendingClueTier was set, used to reject a stale tier.
	private int pendingClueTierTick;

	// Maximum ticks (~0.6s each) between the clue chat line and its Casket loot event.
	private static final int CLUE_TIER_MAX_TICK_GAP = 5;

	private static final String CASKET_EVENT_NAME = "Casket";

	// Line printed when a collection log slot unlocks. Matched after colour tags are stripped.
	private static final Pattern COLLECTION_LOG_ITEM_PATTERN =
		Pattern.compile("New item added to your collection log:\\s*(.+)");

	/**
	 * Chat line printed when a Treasure Trail is completed. Based on Loot Tracker's
	 * CLUE_SCROLL_PATTERN, with a looser tier group that is capitalized in onChatMessage.
	 */
	private static final Pattern CLUE_SCROLL_PATTERN =
		Pattern.compile("You have completed [0-9,]+ ([a-zA-Z]+) Treasure Trails?\\.");

	// Same pattern as RuneLite's ChatCommandsPlugin KILLCOUNT_PATTERN, e.g.
	// "Your Zulrah kill count is: 1,234." Boss names are forwarded as matched and any
	// renaming is done server-side.
	private static final Pattern KILLCOUNT_PATTERN = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?<col=[0-9a-f]{6}>(?<kc>[0-9,]+)</col>");

	/**
	 * Parses chat lines: kill counts, collection log unlocks and clue completions.
	 * Only GAMEMESSAGE and SPAM are checked, as in ChatCommandsPlugin. KILLCOUNT_PATTERN
	 * also matches unrelated "Your ... is: n" lines, which are rejected when both
	 * pre and post are empty, as ChatCommandsPlugin does.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (panel == null)
		{
			return;
		}

		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		// A new collection log slot unlocked. Send the item by name now, since the full
		// capture only runs when the log is opened. Clearing latestCollectionLogItems stops
		// a debounced sync from overwriting this addition with an older full list.
		Matcher collectionLogMatcher = COLLECTION_LOG_ITEM_PATTERN.matcher(Text.removeTags(event.getMessage()));
		if (collectionLogMatcher.find())
		{
			String itemName = collectionLogMatcher.group(1).trim();
			if (!itemName.isEmpty())
			{
				latestCollectionLogItems = null;
				panel.syncCollectionLogItemInBackground(itemName);
			}
			return;
		}

		Matcher clueMatcher = CLUE_SCROLL_PATTERN.matcher(event.getMessage());
		if (clueMatcher.find())
		{
			String tier = clueMatcher.group(1);
			if (tier != null && !tier.isEmpty())
			{
				pendingClueTier = Character.toUpperCase(tier.charAt(0)) + tier.substring(1).toLowerCase();
				pendingClueTierTick = client.getTickCount();
			}
			return;
		}

		Matcher matcher = KILLCOUNT_PATTERN.matcher(event.getMessage());
		if (!matcher.find())
		{
			return;
		}

		String boss = matcher.group("boss");
		String pre = matcher.group("pre");
		String post = matcher.group("post");
		if ((pre == null || pre.isEmpty()) && (post == null || post.isEmpty()))
		{
			return;
		}
		if (boss == null || boss.isEmpty())
		{
			return;
		}

		int killCount;
		try
		{
			killCount = Integer.parseInt(matcher.group("kc").replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return;
		}

		panel.syncKillCountInBackground(boss, killCount);
	}

	// Set when a Potion Storage varp fires and handled on the next game tick, as Bank
	// Tags does, rather than reading script state mid-event. Client thread only.
	private boolean potionStorageDirty;

	private int ticksSincePotionStorageRefresh;

	// Rune Pouch contents or ownership may have changed. Also set from applyContainerSnapshot.
	private boolean runePouchDirty;

	private boolean skillsDirty;

	// Set when the quest complete scroll loads. No single varbit signals every quest.
	private boolean questsDirty;

	private boolean diariesDirty;

	// Set when a combat achievement varbit changes. Only combatTasksCompleted is patched
	// live; the total has no varbit, so it comes from the Character Summary read.
	private boolean combatAchievementsDirty;

	// Set when the collection log count varps change. Both completed and total have varps.
	private boolean collectionsDirty;

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varpId = event.getVarpId();
		if (varpId >= POTION_STORAGE_VARP_MIN && varpId <= POTION_STORAGE_VARP_MAX)
		{
			potionStorageDirty = true;
		}
		if (varpId >= DIARY_TASK_COUNT_FIRST_VARP && varpId < DIARY_TASK_COUNT_FIRST_VARP + DIARY_TASK_COUNT_AREAS.length / 2)
		{
			diariesDirty = true;
		}
		if (varpId == VarPlayerID.COLLECTION_COUNT || varpId == VarPlayerID.COLLECTION_COUNT_MAX)
		{
			collectionsDirty = true;
		}

		int varbitId = event.getVarbitId();
		if (isRunePouchVarbit(varbitId))
		{
			runePouchDirty = true;
		}
		if (DIARY_VARBIT_IDS.contains(varbitId))
		{
			diariesDirty = true;
		}
		if (COMBAT_ACHIEVEMENT_VARBIT_IDS.contains(varbitId))
		{
			combatAchievementsDirty = true;
		}
		if (varbitId == VarbitID.COLLECTION_POH_HOST_BOOK_OPEN)
		{
			collectionLogItemCapture.onAdventureLogVarbitChanged(client);
		}
	}

	/** Entry point for the per-item collection log capture. Fires when the log's setup script runs. */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		collectionLogItemCapture.onCollectionLogOpened(event.getScriptId(), client);
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		collectionLogItemCapture.onScriptPreFired(
			event.getScriptId(), event.getScriptEvent().getArguments(), client);
	}

	/** Boost-only changes are not filtered out; readSkills re-reads every skill and the resend is harmless. */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		skillsDirty = true;
	}

	/**
	 * Flags a quest re-check when the quest complete scroll loads (only the trigger;
	 * Quest#getState provides the data). Also flags the Master Scroll Book and Character
	 * Summary reads and queues virtual storage re-reads (see pendingContainerRereadTicks).
	 */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		int groupId = event.getGroupId();
		if (groupId == InterfaceID.QUESTSCROLL)
		{
			questsDirty = true;
		}
		else if (groupId == InterfaceID.BOOKOFSCROLLS)
		{
			masterScrollBookDirty = true;
		}
		else if (groupId == InterfaceID.ACCOUNT_SUMMARY_SIDEPANEL)
		{
			characterSummaryRereadTicksLeft = CHARACTER_SUMMARY_REREAD_TICKS;
		}

		Integer virtualContainerId = VIRTUAL_STORAGE_WIDGET_CONTAINER_IDS.get(groupId);
		if (virtualContainerId != null)
		{
			queueContainerReread(virtualContainerId);
		}
		else if (groupId == InterfaceID.SAILING_BOAT_CARGOHOLD || groupId == InterfaceID.SAILING_BOAT_CARGOHOLD_SIDE)
		{
			// All five boat slots share this interface and the event does not say which one
			// is open, so queue all five. onGameTick skips those that return null.
			queueContainerReread(InventoryID.SAILING_BOAT_1_CARGOHOLD);
			queueContainerReread(InventoryID.SAILING_BOAT_2_CARGOHOLD);
			queueContainerReread(InventoryID.SAILING_BOAT_3_CARGOHOLD);
			queueContainerReread(InventoryID.SAILING_BOAT_4_CARGOHOLD);
			queueContainerReread(InventoryID.SAILING_BOAT_5_CARGOHOLD);
		}
	}

	private void queueContainerReread(int containerId)
	{
		pendingContainerRereadTicks.put(containerId, client.getTickCount());
	}

	/**
	 * Reads the Master Scroll Book from its widgets (it has no ItemContainer). A widget
	 * with an item id is followed by siblings holding the quantity and the display name.
	 * Child ids are irregular, so the loop matches on adjacency. Zero quantities are
	 * skipped and stray "<br>" is stripped from names.
	 */
	private List<MyscapeClient.MasterScrollBookItem> readMasterScrollBookItems()
	{
		List<MyscapeClient.MasterScrollBookItem> items = new ArrayList<>();
		for (int childId = 0; childId <= 0x54; childId++)
		{
			Widget iconWidget = client.getWidget(InterfaceID.BOOKOFSCROLLS, childId);
			if (iconWidget == null || iconWidget.getItemId() <= 0)
			{
				continue;
			}
			Widget quantityWidget = client.getWidget(InterfaceID.BOOKOFSCROLLS, childId + 1);
			if (quantityWidget == null)
			{
				continue;
			}
			int quantity;
			try
			{
				quantity = Integer.parseInt(quantityWidget.getText().trim());
			}
			catch (NumberFormatException e)
			{
				continue;
			}
			if (quantity <= 0)
			{
				continue;
			}
			Widget nameWidget = client.getWidget(InterfaceID.BOOKOFSCROLLS, childId + 2);
			String name = nameWidget == null ? "" : nameWidget.getText().replace("<br>", "");
			items.add(new MyscapeClient.MasterScrollBookItem(iconWidget.getItemId(), name, quantity));
		}
		return items;
	}

	// Dynamic-child index of each Character Summary stat's value text (found with the
	// Widget Inspector on SUMMARY_CONTENTS). If a game update changes the layout,
	// readCharacterSummary returns null instead of a wrong number.
	private static final int SUMMARY_INDEX_COMBAT_LEVEL = 11;
	private static final int SUMMARY_INDEX_TOTAL_LEVEL = 24;
	private static final int SUMMARY_INDEX_TOTAL_XP = 36;
	private static final int SUMMARY_INDEX_QUESTS = 49;
	private static final int SUMMARY_INDEX_ACHIEVEMENTS = 62;
	private static final int SUMMARY_INDEX_COMBAT_TASKS = 75;
	private static final int SUMMARY_INDEX_COLLECTIONS = 88;

	/** Reads the seven Character Summary stats. Returns null if the panel is closed or parsing fails. */
	private MyscapeClient.CharacterSummaryItem readCharacterSummary()
	{
		Widget contents = client.getWidget(InterfaceID.AccountSummarySidepanel.SUMMARY_CONTENTS);
		if (contents == null)
		{
			return null;
		}
		Widget[] children = contents.getDynamicChildren();
		if (children == null)
		{
			return null;
		}

		Double combatLevel = parseSummaryDecimal(summaryChild(children, SUMMARY_INDEX_COMBAT_LEVEL));
		Integer totalLevel = parseSummaryInt(summaryChild(children, SUMMARY_INDEX_TOTAL_LEVEL));
		Long totalXp = parseSummaryLong(summaryChild(children, SUMMARY_INDEX_TOTAL_XP));
		int[] quests = parseSummaryFraction(summaryChild(children, SUMMARY_INDEX_QUESTS));
		int[] achievements = parseSummaryFraction(summaryChild(children, SUMMARY_INDEX_ACHIEVEMENTS));
		int[] combatTasks = parseSummaryFraction(summaryChild(children, SUMMARY_INDEX_COMBAT_TASKS));
		int[] collections = parseSummaryFraction(summaryChild(children, SUMMARY_INDEX_COLLECTIONS));

		if (combatLevel == null || totalLevel == null || totalXp == null
			|| quests == null || achievements == null || combatTasks == null || collections == null)
		{
			return null;
		}

		return new MyscapeClient.CharacterSummaryItem(
			combatLevel, totalLevel, totalXp,
			quests[0], quests[1],
			achievements[0], achievements[1],
			combatTasks[0], combatTasks[1],
			collections[0], collections[1],
			// Per-tier combat achievement counts are not shown on this panel. They are left
			// zeroed and filled in by patchCombatAchievementStats.
			new int[COMBAT_ACHIEVEMENT_COMPLETED_VARBITS.length],
			readAccountType());
	}

	/**
	 * Maps Varbits.ACCOUNT_TYPE (0-6) to the account type codes used by myscape.io.
	 * Client#getAccountType is not used because it cannot distinguish an unranked
	 * group ironman (runelite/runelite#16510). Unknown values map to "MAIN".
	 */
	private String readAccountType()
	{
		switch (client.getVarbitValue(Varbits.ACCOUNT_TYPE))
		{
			case 1:
				return "IRONMAN";
			case 2:
				return "UIM";
			case 3:
				return "HCIM";
			case 4:
				return "GIM";
			case 5:
				return "HCGIM";
			case 6:
				return "UGIM";
			default:
				return "MAIN";
		}
	}

	private static Widget summaryChild(Widget[] children, int index)
	{
		return index >= 0 && index < children.length ? children[index] : null;
	}

	/** Parses a widget's text, minus colour markup, as a decimal (used for Combat Level). */
	private static Double parseSummaryDecimal(Widget widget)
	{
		if (widget == null || widget.getText() == null)
		{
			return null;
		}
		String cleaned = widget.getText().replaceAll("<[^>]*>", "").trim();
		try
		{
			return Double.parseDouble(cleaned);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static Integer parseSummaryInt(Widget widget)
	{
		if (widget == null || widget.getText() == null)
		{
			return null;
		}
		String digits = widget.getText().replaceAll("<[^>]*>", "").replaceAll("[^0-9]", "");
		if (digits.isEmpty())
		{
			return null;
		}
		try
		{
			return Integer.parseInt(digits);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** Like parseSummaryInt but as a long, since Total XP can exceed Integer.MAX_VALUE. */
	private static Long parseSummaryLong(Widget widget)
	{
		if (widget == null || widget.getText() == null)
		{
			return null;
		}
		String digits = widget.getText().replaceAll("<[^>]*>", "").replaceAll("[^0-9]", "");
		if (digits.isEmpty())
		{
			return null;
		}
		try
		{
			return Long.parseLong(digits);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** Parses an "X/Y" widget into {X, Y} after stripping colour markup. */
	private static int[] parseSummaryFraction(Widget widget)
	{
		if (widget == null || widget.getText() == null)
		{
			return null;
		}
		String cleaned = widget.getText().replaceAll("<[^>]*>", "").trim();
		String[] parts = cleaned.split("/");
		if (parts.length != 2)
		{
			return null;
		}
		try
		{
			return new int[] { Integer.parseInt(parts[0].trim()), Integer.parseInt(parts[1].trim()) };
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * Rebuilds latestCharacterSummary with the fields the caller has fresh data for. A
	 * no-op until readCharacterSummary has established a baseline. Client thread only.
	 */
	private void patchCharacterSummary(UnaryOperator<MyscapeClient.CharacterSummaryItem> patch)
	{
		MyscapeClient.CharacterSummaryItem current = latestCharacterSummary;
		if (current == null)
		{
			return;
		}
		latestCharacterSummary = patch.apply(current);
		scheduleSyncDebounced();
	}

	/**
	 * Patches combat level, total level and total XP from the latest skills, without
	 * needing the Character Summary panel open.
	 */
	private void patchCombatAndTotalStats()
	{
		if (latestSkillItems == null || client.getLocalPlayer() == null)
		{
			return;
		}
		int totalLevel = 0;
		long totalXp = 0;
		for (MyscapeClient.SkillItem item : latestSkillItems)
		{
			totalLevel += item.level;
			totalXp += item.xp;
		}
		double combatLevel = client.getLocalPlayer().getCombatLevel();
		final int finalTotalLevel = totalLevel;
		final long finalTotalXp = totalXp;
		patchCharacterSummary(prev -> new MyscapeClient.CharacterSummaryItem(
			combatLevel, finalTotalLevel, finalTotalXp,
			prev.questsCompleted, prev.questsTotal,
			prev.achievementsCompleted, prev.achievementsTotal,
			prev.combatTasksCompleted, prev.combatTasksTotal,
			prev.collectionsCompleted, prev.collectionsTotal,
			prev.combatTaskTierCompleted,
			prev.accountType));
	}

	private void patchQuestStats()
	{
		if (latestCompletedQuestNames == null)
		{
			return;
		}
		int completed = latestCompletedQuestNames.size();
		int total = Quest.values().length;
		patchCharacterSummary(prev -> new MyscapeClient.CharacterSummaryItem(
			prev.combatLevel, prev.totalLevel, prev.totalXp,
			completed, total,
			prev.achievementsCompleted, prev.achievementsTotal,
			prev.combatTasksCompleted, prev.combatTasksTotal,
			prev.collectionsCompleted, prev.collectionsTotal,
			prev.combatTaskTierCompleted,
			prev.accountType));
	}

	/**
	 * Patches the achievement count from latestDiaryTierItems: the number of tasks completed
	 * across all areas, with the total left as the Character Summary last reported it. Before
	 * that total is known it falls back to counting completed tiers out of 12 areas x 4.
	 */
	private void patchDiaryStats()
	{
		if (latestDiaryTierItems == null)
		{
			return;
		}
		int tasks = 0;
		int tiers = 0;
		for (MyscapeClient.DiaryTierItem item : latestDiaryTierItems)
		{
			if (item.taskCounts != null)
			{
				for (int count : item.taskCounts)
				{
					tasks += count;
				}
			}
			for (int i = 0; i < DIARY_TIER_NAMES.length; i++)
			{
				if (DIARY_TIER_NAMES[i].equals(item.tier))
				{
					tiers += i + 1;
					break;
				}
			}
		}
		final int finalTasks = tasks;
		final int finalTiers = tiers;
		final int tierTotal = DIARY_VARBIT_IDS.size();
		patchCharacterSummary(prev -> new MyscapeClient.CharacterSummaryItem(
			prev.combatLevel, prev.totalLevel, prev.totalXp,
			prev.questsCompleted, prev.questsTotal,
			prev.achievementsTotal > tierTotal ? finalTasks : finalTiers,
			prev.achievementsTotal > tierTotal ? prev.achievementsTotal : tierTotal,
			prev.combatTasksCompleted, prev.combatTasksTotal,
			prev.collectionsCompleted, prev.collectionsTotal,
			prev.combatTaskTierCompleted,
			prev.accountType));
	}

	/**
	 * Patches combatTasksCompleted and the per-tier counts. combatTasksTotal has no
	 * varbit and keeps its last Character Summary value.
	 */
	private void patchCombatAchievementStats()
	{
		int completed = 0;
		int[] tierCompleted = new int[COMBAT_ACHIEVEMENT_COMPLETED_VARBITS.length];
		for (int i = 0; i < COMBAT_ACHIEVEMENT_COMPLETED_VARBITS.length; i++)
		{
			int value = client.getVarbitValue(COMBAT_ACHIEVEMENT_COMPLETED_VARBITS[i]);
			tierCompleted[i] = value;
			completed += value;
		}
		final int finalCompleted = completed;
		final int[] finalTierCompleted = tierCompleted;
		patchCharacterSummary(prev -> new MyscapeClient.CharacterSummaryItem(
			prev.combatLevel, prev.totalLevel, prev.totalXp,
			prev.questsCompleted, prev.questsTotal,
			prev.achievementsCompleted, prev.achievementsTotal,
			finalCompleted, prev.combatTasksTotal,
			prev.collectionsCompleted, prev.collectionsTotal,
			finalTierCompleted,
			prev.accountType));
	}

	/**
	 * Patches the collection log counts from COLLECTION_COUNT and COLLECTION_COUNT_MAX.
	 * A value of 0 is treated as not yet populated, as in DinkPlugin's CollectionNotifier.
	 */
	private void patchCollectionStats()
	{
		int completed = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		if (completed <= 0 || total <= 0)
		{
			return;
		}
		patchCharacterSummary(prev -> new MyscapeClient.CharacterSummaryItem(
			prev.combatLevel, prev.totalLevel, prev.totalXp,
			prev.questsCompleted, prev.questsTotal,
			prev.achievementsCompleted, prev.achievementsTotal,
			prev.combatTasksCompleted, prev.combatTasksTotal,
			completed, total,
			prev.combatTaskTierCompleted,
			prev.accountType));
	}

	/** Whether varbitId is one of the 12 Rune Pouch varbits (not contiguous, so matched by exact id). */
	private static boolean isRunePouchVarbit(int varbitId)
	{
		if (varbitId < 0)
		{
			return false;
		}
		for (int id : RUNE_POUCH_TYPE_VARBITS)
		{
			if (id == varbitId)
			{
				return true;
			}
		}
		for (int id : RUNE_POUCH_QUANTITY_VARBITS)
		{
			if (id == varbitId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * (Re)schedules the single debounce task shared by all sources. When it fires it
	 * syncs whichever sources have been seen, reading only the captured snapshots since
	 * it runs on the executor thread. The delay is clamped so a long burst still syncs
	 * at SYNC_MAX_WAIT_SECONDS.
	 */
	private void scheduleSyncDebounced()
	{
		long now = System.currentTimeMillis();
		if (syncBurstStartMillis < 0)
		{
			syncBurstStartMillis = now;
		}
		long elapsedSeconds = (now - syncBurstStartMillis) / 1000;
		long delaySeconds = Math.max(0, Math.min(SYNC_DEBOUNCE_SECONDS, SYNC_MAX_WAIT_SECONDS - elapsedSeconds));

		if (syncDebounceTask != null)
		{
			syncDebounceTask.cancel(false);
		}
		syncDebounceTask = executor.schedule(
			() -> {
				syncBurstStartMillis = -1;
				if (panel != null)
				{
					panel.syncInBackground(
						latestBankItems, latestInventoryItems, latestEquipmentItems,
						latestPotionStorageItems, latestRunePouchItems, latestLootingBagItems,
						latestSeedVaultItems, latestTackleBoxItems, latestPohItems,
						latestForestryKitItems, latestSeedBoxItems, latestMasterScrollBookItems,
						latestSkillItems, latestCompletedQuestNames, latestInProgressQuestNames,
						latestDiaryTierItems,
						latestHuntsmansKitItems, latestBoatCargo1Items, latestBoatCargo2Items,
						latestBoatCargo3Items, latestBoatCargo4Items, latestBoatCargo5Items,
						latestCharacterSummary, latestCollectionLogItems);
				}
			},
			delaySeconds, TimeUnit.SECONDS);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!MyscapeConfig.GROUP.equals(event.getGroup()) || !"showSidebar".equals(event.getKey()))
		{
			return;
		}
		if (config.showSidebar())
		{
			clientToolbar.addNavigation(navButton);
		}
		else
		{
			clientToolbar.removeNavigation(navButton);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.LOGGING_IN)
		{
			currentAccountHash = null;
			currentRuneScapeName = null;
		}
		if (panel != null)
		{
			panel.onGameStateChanged();
		}
	}

	/**
	 * Sends the display name to myscape.io when it differs from the last one accepted.
	 * Runs on the client thread; the HTTP call is async.
	 */
	private void reportRuneScapeNameIfChanged()
	{
		String name = currentRuneScapeName;
		Long accountHash = currentAccountHash;
		if (panel == null || name == null || name.isEmpty() || accountHash == null || accountHash == -1L
			|| name.equals(lastReportedRuneScapeName))
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (now < nameReportCooldownUntilMillis)
		{
			return;
		}
		nameReportCooldownUntilMillis = now + NAME_REPORT_RETRY_MILLIS;
		panel.syncRunescapeNameInBackground(accountHash, name, () -> lastReportedRuneScapeName = name);
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// The local player and name can take a tick or two to become available after
		// GameState flips to LOGGED_IN, so keep both cached values current.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			boolean justBecameAvailable = currentAccountHash == null;
			currentAccountHash = client.getAccountHash();
			if (client.getLocalPlayer() != null)
			{
				currentRuneScapeName = client.getLocalPlayer().getName();
				reportRuneScapeNameIfChanged();
			}

			// Read Potion Storage one tick after a tracked varp fired (see potionStorageDirty)
			// or when the periodic refresh interval has elapsed.
			if (potionStorageDirty || ++ticksSincePotionStorageRefresh >= POTION_STORAGE_REFRESH_INTERVAL_TICKS)
			{
				potionStorageDirty = false;
				ticksSincePotionStorageRefresh = 0;
				latestPotionStorageItems = readPotionStorageItems();
				scheduleSyncDebounced();
			}

			if (runePouchDirty)
			{
				runePouchDirty = false;
				latestRunePouchItems = readRunePouchItems();
				scheduleSyncDebounced();
			}

			if (skillsDirty)
			{
				skillsDirty = false;
				latestSkillItems = readSkills();
				scheduleSyncDebounced();
				patchCombatAndTotalStats();
			}

			if (questsDirty)
			{
				questsDirty = false;
				latestCompletedQuestNames = readCompletedQuestNames();
				latestInProgressQuestNames = readInProgressQuestNames();
				scheduleSyncDebounced();
				patchQuestStats();
			}

			if (diariesDirty)
			{
				diariesDirty = false;
				latestDiaryTierItems = readDiaryTiers();
				scheduleSyncDebounced();
				patchDiaryStats();
			}

			if (combatAchievementsDirty)
			{
				combatAchievementsDirty = false;
				patchCombatAchievementStats();
			}

			if (collectionsDirty)
			{
				collectionsDirty = false;
				patchCollectionStats();
			}

			// A collection log item capture does not complete on a single event: the client
			// fires one script per obtained item with no end marker. collectionLogItemCapture
			// decides a pass is finished once no new item has arrived for a couple of ticks.
			if (collectionLogItemCapture.onGameTick(client))
			{
				List<MyscapeClient.CollectionLogItem> items = new ArrayList<>();
				for (Map.Entry<Integer, Integer> entry : collectionLogItemCapture.snapshotCapturedItems().entrySet())
				{
					items.add(new MyscapeClient.CollectionLogItem(entry.getKey(), entry.getValue()));
				}
				latestCollectionLogItems = items;
				scheduleSyncDebounced();
			}

			if (masterScrollBookDirty)
			{
				masterScrollBookDirty = false;
				latestMasterScrollBookItems = readMasterScrollBookItems();
				scheduleSyncDebounced();
			}

			if (characterSummaryRereadTicksLeft > 0)
			{
				characterSummaryRereadTicksLeft--;
				MyscapeClient.CharacterSummaryItem summary = readCharacterSummary();
				if (summary != null)
				{
					latestCharacterSummary = summary;
					scheduleSyncDebounced();
					// readCharacterSummary zeroes combatTaskTierCompleted. Patch it here so the
					// per-tier breakdown is correct as soon as the panel is first opened, instead of
					// only after the next combat task is completed.
					patchCombatAchievementStats();
				}
			}

			// Consume pendingContainerRereadTicks: once this tick is after the widget's, read the
			// container explicitly, since no ItemContainerChanged fires for an already-empty
			// storage. A null read stays queued until MAX_CONTAINER_REREAD_WAIT_TICKS passes.
			// Entries are removed via the iterator to avoid a ConcurrentModificationException.
			if (!pendingContainerRereadTicks.isEmpty())
			{
				int currentTick = client.getTickCount();
				Iterator<Map.Entry<Integer, Integer>> pendingIterator = pendingContainerRereadTicks.entrySet().iterator();
				while (pendingIterator.hasNext())
				{
					Map.Entry<Integer, Integer> pending = pendingIterator.next();
					int containerId = pending.getKey();
					int queuedTick = pending.getValue();
					if (currentTick > queuedTick)
					{
						ItemContainer container = client.getItemContainer(containerId);
						if (container != null)
						{
							pendingIterator.remove();
							if (applyContainerSnapshot(containerId, container))
							{
								scheduleSyncDebounced();
							}
						}
						else if (currentTick - queuedTick > MAX_CONTAINER_REREAD_WAIT_TICKS)
						{
							pendingIterator.remove();
						}
					}
				}
			}

			// onGameStateChanged fires when the state flips to LOGGED_IN, but getAccountHash()
			// is not populated until this tick (and no event fires at all if the plugin starts
			// while already in game). Notify the panel again once the hash is available.
			if (justBecameAvailable)
			{
				if (panel != null)
				{
					panel.onGameStateChanged();
				}

				// Inventory and equipment are populated at login, unlike the bank, so capture
				// them now for an accurate initial snapshot.
				ItemContainer inventory = client.getItemContainer(InventoryID.INV);
				if (inventory != null)
				{
					latestInventoryItems = readInventoryItems(inventory);
				}
				ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
				if (equipment != null)
				{
					latestEquipmentItems = readEquipmentItems(equipment);
				}
				// Potion Storage has no container and is otherwise read only after a tracked
				// varp fires, so read it once here. The periodic refresh keeps it current.
				latestPotionStorageItems = readPotionStorageItems();
				ticksSincePotionStorageRefresh = 0;
				latestRunePouchItems = readRunePouchItems();
				// Skills, quests and diaries are fully known at login. Capture them now so
				// existing progress is reported without waiting for a change.
				latestSkillItems = readSkills();
				latestCompletedQuestNames = readCompletedQuestNames();
				latestInProgressQuestNames = readInProgressQuestNames();
				latestDiaryTierItems = readDiaryTiers();
				scheduleSyncDebounced();
			}
		}
	}

	/** The account hash to link with, or null if not logged in. Safe to call from the EDT. */
	Long getAccountHash()
	{
		return currentAccountHash;
	}

	/** The current display name, or null if not yet known. Informational only. Safe to call from the EDT. */
	String getRuneScapeName()
	{
		return currentRuneScapeName;
	}

	/** Called on the client thread (not the EDT) when a model capture finishes. */
	interface ModelCaptureCallback
	{
		void onSuccess(byte[] glb);

		void onFailure(String message);
	}

	/**
	 * Captures the local player's current model as a .glb file. A Model's vertex and face
	 * arrays are only valid on the client thread, so the read and conversion run in one
	 * clientThread.invoke. See the modelexport package.
	 */
	void captureCharacterModel(ModelCaptureCallback callback)
	{
		clientThread.invoke(() ->
		{
			Player localPlayer = client.getLocalPlayer();
			if (localPlayer == null)
			{
				callback.onFailure("Log into the game first.");
				return;
			}
			Model model = localPlayer.getModel();
			if (model == null)
			{
				callback.onFailure("Character isn't ready to capture yet -- try again in a moment.");
				return;
			}
			try
			{
				// Use the client's TextureProvider if available for its brightness setting and real
				// texture pixels. Without it, textured faces fall back to flat vertex colours.
				TextureProvider textureProvider = client.getTextureProvider();
				byte[] glb = textureProvider != null
					? ModelExporter.captureGlb(model, textureProvider.getBrightness(), textureProvider)
					: ModelExporter.captureGlb(model);
				callback.onSuccess(glb);
			}
			catch (Exception e)
			{
				log.warn("Failed to capture character model", e);
				callback.onFailure("Something went wrong capturing your character model.");
			}
		});
	}
}

package io.myscape.plugin.collectionlog;

import java.util.LinkedHashMap;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;

/**
 * Captures which collection log items the player has obtained, and their quantities.
 *
 * <p>Obtained state is only readable by opening the collection log in-game. This class
 * re-triggers the client's search-then-reset refresh and accumulates the per-item id/quantity
 * broadcast. Event registration stays in {@code MyscapePlugin}, which passes in event data.
 *
 * <p>Technique credit: RuneProfile's plugin (github.com/RuneProfile/runeprofile-plugin,
 * BSD-2-Clause), which credits WikiSync (github.com/weirdgloop/WikiSync, BSD-2-Clause).
 * The script ids and the two-tick settle buffer follow those projects.
 */
public final class CollectionLogItemCapture
{
	/** Fires once per obtained item after the refresh. args[1] is the item id, args[2] the quantity. */
	private static final int COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID = 4100;

	/** Fires whenever the collection log finishes setup, including after our own re-trigger. */
	private static final int COLLECTION_LOG_SETUP_SCRIPT_ID = 7797;

	/** Run after toggling search on then off; makes the client transmit every obtained item. */
	private static final int COLLECTION_LOG_INIT_SCRIPT_ID = 2240;

	/** Ticks without an item transmission after which a pass counts as finished (no explicit end signal exists). */
	private static final int SETTLE_BUFFER_TICKS = 2;

	/** Item id -> quantity, in the order the client sent them. */
	private final Map<Integer, Integer> capturedItems = new LinkedHashMap<>();

	/**
	 * Ids announced by the item script that differ from the id the log structure lists
	 * (see {@link CollectionLogSchemaExporter}). The Yama Dossier is announced as its
	 * placeholder variant 30805 but listed as 30803.
	 */
	private static final Map<Integer, Integer> ANNOUNCED_ID_TO_STRUCTURE_ID = buildAnnouncedIdRemap();

	private static Map<Integer, Integer> buildAnnouncedIdRemap()
	{
		Map<Integer, Integer> remap = new HashMap<>();
		remap.put(30805, 30803); // Dossier (Yama)
		return Collections.unmodifiableMap(remap);
	}

	/** True from the start of a capture until {@link #onGameTick} sees it settle; stops the setup re-fire from re-triggering. */
	private boolean triggeringCapture;

	/** Client tick of the last item transmission, or -1 when no capture pass is in flight. Client thread only. */
	private int lastItemScriptFiredTick = -1;

	/**
	 * Call for every script post-fire. On the setup script, starts a capture by toggling "Search"
	 * on then off and re-running the init script. Clears data and returns when the log was
	 * opened from another player's adventure log book.
	 */
	public void onCollectionLogOpened(int scriptId, Client client)
	{
		if (scriptId != COLLECTION_LOG_SETUP_SCRIPT_ID)
		{
			return;
		}

		if (isOpenedFromAdventureLog(client))
		{
			capturedItems.clear();
			return;
		}

		if (triggeringCapture)
		{
			return;
		}

		triggeringCapture = true;
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(COLLECTION_LOG_INIT_SCRIPT_ID);
	}

	/** Call for every script pre-fire; ignores all but the item transmission script. */
	public void onScriptPreFired(int scriptId, Object[] scriptArgs, Client client)
	{
		if (scriptId != COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID)
		{
			return;
		}

		if (isOpenedFromAdventureLog(client))
		{
			return;
		}

		lastItemScriptFiredTick = client.getTickCount();

		int itemId = ANNOUNCED_ID_TO_STRUCTURE_ID.getOrDefault((int) scriptArgs[1], (int) scriptArgs[1]);
		int quantity = (int) scriptArgs[2];
		// The script only fires for obtained items, so store at least 1 even if the
		// quantity argument is lower (the server treats under 1 as not obtained).
		capturedItems.put(itemId, Math.max(1, quantity));
	}

	/** Call when {@code VarbitID.COLLECTION_POH_HOST_BOOK_OPEN} changes. Fail-safe for the book opening between script firings. */
	public void onAdventureLogVarbitChanged(Client client)
	{
		if (isOpenedFromAdventureLog(client))
		{
			capturedItems.clear();
		}
	}

	/** Call each {@code GameTick}. Returns true once per pass, {@link #SETTLE_BUFFER_TICKS} ticks after the last item. */
	public boolean onGameTick(Client client)
	{
		boolean hasCapturePassInFlight = lastItemScriptFiredTick != -1;
		boolean settleBufferElapsed = lastItemScriptFiredTick + SETTLE_BUFFER_TICKS < client.getTickCount();
		if (hasCapturePassInFlight && settleBufferElapsed)
		{
			lastItemScriptFiredTick = -1;
			triggeringCapture = false;
			return true;
		}
		return false;
	}

	/** Returns a copy of the captured item id -> quantity map, safe to hold across ticks. */
	public Map<Integer, Integer> snapshotCapturedItems()
	{
		return new LinkedHashMap<>(capturedItems);
	}

	private static boolean isOpenedFromAdventureLog(Client client)
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
	}
}

package io.myscape.plugin.collectionlog;

import java.util.Collections;
import java.util.List;

/**
 * The collection log's tab/page/item structure, without any obtained or quantity state.
 * It is identical for every player on a given game build, so it is exported once from cache
 * data. See {@link CollectionLogSchemaExporter}.
 */
public final class CollectionLogSchema
{
	private final List<Tab> tabs;

	public CollectionLogSchema(List<Tab> tabs)
	{
		this.tabs = Collections.unmodifiableList(tabs);
	}

	public List<Tab> getTabs()
	{
		return tabs;
	}

	/** A top-level tab (Bosses, Raids, Clues, Minigames, Other). */
	public static final class Tab
	{
		private final String name;
		private final List<Page> pages;

		public Tab(String name, List<Page> pages)
		{
			this.name = name;
			this.pages = Collections.unmodifiableList(pages);
		}

		public String getName()
		{
			return name;
		}

		public List<Page> getPages()
		{
			return pages;
		}
	}

	/** A page within a tab (e.g. "Zulrah"). itemIds lists every item the page can show, in in-game order. */
	public static final class Page
	{
		private final String name;
		private final List<Integer> itemIds;

		public Page(String name, List<Integer> itemIds)
		{
			this.name = name;
			this.itemIds = Collections.unmodifiableList(itemIds);
		}

		public String getName()
		{
			return name;
		}

		public List<Integer> getItemIds()
		{
			return itemIds;
		}
	}
}

package io.myscape.plugin.collectionlog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;

/**
 * Reads the collection log's tab/page/item structure from the client's cache data (struct and
 * enum compositions). Structure only: obtained state is not cache data and is captured
 * separately by {@link CollectionLogItemCapture}.
 *
 * <p>Credit: the tab struct ids and the struct param ids below, and the read order, come from the
 * BSD-2-Clause "Collection Log" plugin (github.com/evansloan/collection-log,
 * CollectionLogManager#initCollectionLog).
 */
public final class CollectionLogSchemaExporter
{
	/** Top-level tab structs, in in-game order. */
	private static final List<Integer> TAB_STRUCT_IDS = Collections.unmodifiableList(
		java.util.Arrays.asList(471, 472, 473, 474, 475) // Bosses, Raids, Clues, Minigames, Other
	);

	private static final int TAB_NAME_PARAM_ID = 682;
	private static final int TAB_PAGE_ENUM_PARAM_ID = 683;
	private static final int PAGE_NAME_PARAM_ID = 689;
	private static final int PAGE_ITEMS_ENUM_PARAM_ID = 690;

	/**
	 * Items whose id in a page's item enum differs from the id the collection log widget
	 * displays. Without this remap the same drop would appear under two ids and fail to match
	 * a live capture. Values are from evansloan/collection-log (ITEM_ID_MAP).
	 */
	private static final Map<Integer, Integer> PAGE_STRUCT_ITEM_ID_TO_WIDGET_ITEM_ID = buildItemIdRemap();

	private static Map<Integer, Integer> buildItemIdRemap()
	{
		Map<Integer, Integer> remap = new HashMap<>();
		remap.put(10859, 25617); // Tea flask
		remap.put(10877, 25618); // Red satchel
		remap.put(10878, 25619); // Green satchel
		remap.put(10879, 25620); // Red satchel
		remap.put(10880, 25621); // Black satchel
		remap.put(10881, 25622); // Gold satchel
		remap.put(10882, 25623); // Rune satchel
		remap.put(13273, 25624); // Unsired
		remap.put(12019, 25627); // Coal bag
		remap.put(12020, 25628); // Gem bag
		remap.put(24882, 25629); // Plank sack
		remap.put(12854, 25630); // Flamtaer bag
		return Collections.unmodifiableMap(remap);
	}

	private CollectionLogSchemaExporter()
	{
	}

	/**
	 * Walks the tab structs and everything they reference into a {@link CollectionLogSchema}.
	 * Needs only a loaded cache, not an open widget. Call from the client thread.
	 */
	public static CollectionLogSchema export(Client client)
	{
		List<CollectionLogSchema.Tab> tabs = new ArrayList<>();

		for (int tabStructId : TAB_STRUCT_IDS)
		{
			StructComposition tabStruct = client.getStructComposition(tabStructId);
			String tabName = tabStruct.getStringValue(TAB_NAME_PARAM_ID);
			int tabPageEnumId = tabStruct.getIntValue(TAB_PAGE_ENUM_PARAM_ID);
			EnumComposition tabPageEnum = client.getEnum(tabPageEnumId);
			// getEnum can return null for an unresolved id; skip the tab rather than fail the export.
			if (tabPageEnum == null)
			{
				continue;
			}

			List<CollectionLogSchema.Page> pages = new ArrayList<>();
			for (int pageStructId : tabPageEnum.getIntVals())
			{
				pages.add(readPage(client, pageStructId));
			}

			tabs.add(new CollectionLogSchema.Tab(tabName, pages));
		}

		return new CollectionLogSchema(tabs);
	}

	private static CollectionLogSchema.Page readPage(Client client, int pageStructId)
	{
		StructComposition pageStruct = client.getStructComposition(pageStructId);
		String pageName = pageStruct.getStringValue(PAGE_NAME_PARAM_ID);
		int pageItemsEnumId = pageStruct.getIntValue(PAGE_ITEMS_ENUM_PARAM_ID);
		EnumComposition pageItemsEnum = client.getEnum(pageItemsEnumId);

		List<Integer> itemIds = new ArrayList<>();
		if (pageItemsEnum == null)
		{
			return new CollectionLogSchema.Page(pageName, itemIds);
		}

		for (int rawItemId : pageItemsEnum.getIntVals())
		{
			Integer remapped = PAGE_STRUCT_ITEM_ID_TO_WIDGET_ITEM_ID.get(rawItemId);
			itemIds.add(remapped != null ? remapped : rawItemId);
		}

		return new CollectionLogSchema.Page(pageName, itemIds);
	}
}

package io.myscape.plugin.modelexport;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.ByteArrayOutputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Serializes a {@link MeshData} into a binary glTF 2.0 (.glb) file: a JSON chunk plus one binary
 * chunk holding vertex, index and image bytes. The JSON is built with Gson, with no glTF library.
 *
 * <p>Textures: PNG bytes supplied per texture id (see {@link TextureExtractor}) are embedded as
 * {@code images}/{@code textures} and referenced as {@code baseColorTexture}. {@code baseColorFactor}
 * stays white and COLOR_0 (the lightness multiplier from {@link HslColor#textureLightnessToRgb})
 * modulates the sampled color, which glTF defines and KHR_materials_unlit does not change. A
 * primitive with no PNG falls back to a vertex-color-only material.
 *
 * <p>Render priority/bias: each primitive carries OSRS priority and bias as glTF {@code extras}.
 * Neither glTF nor three.js has an equivalent, so a viewer can map them to a render order.
 *
 * <p>Materials use KHR_materials_unlit because the game already bakes lighting into each face's HSL
 * color, and extra scene lighting would double-light the model.
 */
final class GlbWriter
{
	private GlbWriter()
	{
	}

	private static final int GLB_MAGIC = 0x46546C67; // ASCII "glTF" read little-endian.
	private static final int GLB_VERSION = 2;
	private static final int CHUNK_TYPE_JSON = 0x4E4F534A; // ASCII "JSON" read little-endian.
	private static final int CHUNK_TYPE_BIN = 0x004E4942; // ASCII "BIN\0" read little-endian.
	private static final int GLB_HEADER_LENGTH = 12;
	private static final int CHUNK_HEADER_LENGTH = 8;

	private static final int COMPONENT_TYPE_UNSIGNED_SHORT = 5123;
	private static final int COMPONENT_TYPE_UNSIGNED_INT = 5125;
	private static final int COMPONENT_TYPE_FLOAT = 5126;

	private static final int TARGET_ARRAY_BUFFER = 34962;
	private static final int TARGET_ELEMENT_ARRAY_BUFFER = 34963;

	// glTF sampler enums (WebGL/OpenGL constants).
	private static final int FILTER_NEAREST = 9728;
	private static final int WRAP_REPEAT = 10497;

	/** Writes {@code mesh} with untextured materials. */
	static byte[] write(MeshData mesh)
	{
		return write(mesh, Collections.emptyMap());
	}

	/**
	 * Writes {@code mesh}, embedding textures where available.
	 *
	 * @param texturePngs PNG bytes per OSRS texture id (see {@link TextureExtractor#extractPngs});
	 *                    primitives without an entry use vertex-color-only materials
	 */
	static byte[] write(MeshData mesh, Map<Integer, byte[]> texturePngs)
	{
		BinaryBuffer bin = new BinaryBuffer();
		JsonArray bufferViews = new JsonArray();
		JsonArray accessors = new JsonArray();

		int positionAccessor = writeVec3Accessor(mesh.positions, mesh.boundsMin, mesh.boundsMax, bin, bufferViews, accessors);
		int colorAccessor = writeVec4Accessor(mesh.colors, bin, bufferViews, accessors);
		Integer uvAccessor = mesh.uvs != null ? writeVec2Accessor(mesh.uvs, bin, bufferViews, accessors) : null;

		// Unsigned-short indices address at most 65535 vertices; larger meshes need unsigned int.
		boolean useIntIndices = mesh.positions.size() > 65535;

		JsonArray primitivesJson = new JsonArray();
		JsonArray materialsJson = new JsonArray();
		Map<Long, Integer> materialIndexByKey = new LinkedHashMap<>();

		JsonArray imagesJson = new JsonArray();
		JsonArray samplersJson = new JsonArray();
		JsonArray texturesJson = new JsonArray();
		// OSRS texture id -> glTF `textures` index, so a texture shared by primitives is embedded once.
		Map<Integer, Integer> glTfTextureIndexByTextureId = new LinkedHashMap<>();

		for (MeshData.Primitive primitive : mesh.primitives)
		{
			if (primitive.indices.isEmpty())
			{
				// An empty primitive is invalid glTF (all its faces were dropped), so skip it.
				continue;
			}

			long materialKey = ((long) (primitive.textureId + 1) << 1) | (primitive.translucent ? 1 : 0);
			Integer materialIndex = materialIndexByKey.get(materialKey);
			if (materialIndex == null)
			{
				Integer glTfTextureIndex = null;
				byte[] png = primitive.textureId >= 0 ? texturePngs.get(primitive.textureId) : null;
				if (png != null)
				{
					glTfTextureIndex = glTfTextureIndexByTextureId.get(primitive.textureId);
					if (glTfTextureIndex == null)
					{
						if (samplersJson.size() == 0)
						{
							samplersJson.add(buildSampler());
						}
						int imageIndex = writeImage(png, bin, bufferViews, imagesJson);
						JsonObject textureJson = new JsonObject();
						textureJson.addProperty("sampler", 0);
						textureJson.addProperty("source", imageIndex);
						glTfTextureIndex = texturesJson.size();
						texturesJson.add(textureJson);
						glTfTextureIndexByTextureId.put(primitive.textureId, glTfTextureIndex);
					}
				}

				materialIndex = materialsJson.size();
				materialIndexByKey.put(materialKey, materialIndex);
				materialsJson.add(buildMaterial(primitive.translucent, glTfTextureIndex));
			}

			int indicesAccessor = writeIndicesAccessor(primitive.indices, useIntIndices, bin, bufferViews, accessors);

			JsonObject attributes = new JsonObject();
			attributes.addProperty("POSITION", positionAccessor);
			attributes.addProperty("COLOR_0", colorAccessor);
			if (uvAccessor != null)
			{
				attributes.addProperty("TEXCOORD_0", uvAccessor);
			}

			JsonObject primitiveJson = new JsonObject();
			primitiveJson.add("attributes", attributes);
			primitiveJson.addProperty("indices", indicesAccessor);
			primitiveJson.addProperty("material", materialIndex);
			primitiveJson.addProperty("mode", 4); // TRIANGLES
			// Priority/bias go in an extras object because three.js GLTFLoader copies extras to
			// userData only when they are an object.
			// missingTexture marks a primitive that wanted a texture the extractor could not
			// supply. It would otherwise render as a flat bright patch, so the viewer dims it.
			boolean missingTexture = primitive.textureId >= 0 && !texturePngs.containsKey(primitive.textureId);
			JsonObject extras = new JsonObject();
			extras.addProperty("osrsPriority", primitive.priority);
			extras.addProperty("osrsBias", primitive.bias);
			extras.addProperty("missingTexture", missingTexture);
			primitiveJson.add("extras", extras);
			primitivesJson.add(primitiveJson);
		}

		JsonObject meshJson = new JsonObject();
		meshJson.add("primitives", primitivesJson);
		JsonArray meshesJson = new JsonArray();
		meshesJson.add(meshJson);

		JsonObject nodeJson = new JsonObject();
		nodeJson.addProperty("mesh", 0);
		JsonArray nodesJson = new JsonArray();
		nodesJson.add(nodeJson);

		JsonArray sceneNodes = new JsonArray();
		sceneNodes.add(0);
		JsonObject sceneJson = new JsonObject();
		sceneJson.add("nodes", sceneNodes);
		JsonArray scenesJson = new JsonArray();
		scenesJson.add(sceneJson);

		JsonObject assetJson = new JsonObject();
		assetJson.addProperty("version", "2.0");
		assetJson.addProperty("generator", "myscape-plugin model exporter");

		JsonObject bufferJson = new JsonObject();
		bufferJson.addProperty("byteLength", bin.size());
		JsonArray buffersJson = new JsonArray();
		buffersJson.add(bufferJson);

		JsonArray extensionsUsed = new JsonArray();
		extensionsUsed.add("KHR_materials_unlit");

		JsonObject root = new JsonObject();
		root.add("asset", assetJson);
		root.add("extensionsUsed", extensionsUsed);
		root.addProperty("scene", 0);
		root.add("scenes", scenesJson);
		root.add("nodes", nodesJson);
		root.add("meshes", meshesJson);
		root.add("materials", materialsJson);
		if (imagesJson.size() > 0)
		{
			root.add("images", imagesJson);
			root.add("samplers", samplersJson);
			root.add("textures", texturesJson);
		}
		root.add("accessors", accessors);
		root.add("bufferViews", bufferViews);
		root.add("buffers", buffersJson);

		byte[] json = root.toString().getBytes(StandardCharsets.UTF_8);
		return assembleGlb(json, bin.toByteArray());
	}

	private static JsonObject buildMaterial(boolean translucent, Integer glTfTextureIndex)
	{
		JsonObject pbr = new JsonObject();
		JsonArray baseColorFactor = new JsonArray();
		baseColorFactor.add(1.0f);
		baseColorFactor.add(1.0f);
		baseColorFactor.add(1.0f);
		baseColorFactor.add(1.0f);
		pbr.add("baseColorFactor", baseColorFactor);
		pbr.addProperty("metallicFactor", 0.0f);
		pbr.addProperty("roughnessFactor", 1.0f);
		if (glTfTextureIndex != null)
		{
			// Added alongside baseColorFactor and COLOR_0; see class doc.
			JsonObject baseColorTexture = new JsonObject();
			baseColorTexture.addProperty("index", glTfTextureIndex);
			baseColorTexture.addProperty("texCoord", 0);
			pbr.add("baseColorTexture", baseColorTexture);
		}

		JsonObject material = new JsonObject();
		material.add("pbrMetallicRoughness", pbr);
		material.addProperty("alphaMode", translucent ? "BLEND" : "OPAQUE");
		// OSRS draws both sides of thin gear and cloth geometry.
		material.addProperty("doubleSided", true);

		JsonObject unlit = new JsonObject();
		JsonObject extensions = new JsonObject();
		extensions.add("KHR_materials_unlit", unlit);
		material.add("extensions", extensions);

		return material;
	}

	/**
	 * One sampler shared by all textures. Nearest filtering matches the game's GPU plugin and keeps
	 * texture detail crisp. Repeat wrap because UVs can fall outside 0..1 for tiled patterns.
	 */
	private static JsonObject buildSampler()
	{
		JsonObject sampler = new JsonObject();
		sampler.addProperty("magFilter", FILTER_NEAREST);
		sampler.addProperty("minFilter", FILTER_NEAREST);
		sampler.addProperty("wrapS", WRAP_REPEAT);
		sampler.addProperty("wrapT", WRAP_REPEAT);
		return sampler;
	}

	private static int writeVec3Accessor(java.util.List<float[]> vectors, float[] min, float[] max,
		BinaryBuffer bin, JsonArray bufferViews, JsonArray accessors)
	{
		bin.align4();
		int byteOffset = bin.size();
		for (float[] v : vectors)
		{
			bin.writeFloat(v[0]);
			bin.writeFloat(v[1]);
			bin.writeFloat(v[2]);
		}
		int byteLength = vectors.size() * 3 * 4;

		int bufferViewIndex = bufferViews.size();
		bufferViews.add(buildBufferView(byteOffset, byteLength, TARGET_ARRAY_BUFFER));

		JsonObject accessor = new JsonObject();
		accessor.addProperty("bufferView", bufferViewIndex);
		accessor.addProperty("componentType", COMPONENT_TYPE_FLOAT);
		accessor.addProperty("count", vectors.size());
		accessor.addProperty("type", "VEC3");
		// glTF requires min/max on the POSITION accessor.
		accessor.add("min", floatArray(min[0], min[1], min[2]));
		accessor.add("max", floatArray(max[0], max[1], max[2]));
		int accessorIndex = accessors.size();
		accessors.add(accessor);
		return accessorIndex;
	}

	private static int writeVec4Accessor(java.util.List<float[]> vectors, BinaryBuffer bin, JsonArray bufferViews, JsonArray accessors)
	{
		bin.align4();
		int byteOffset = bin.size();
		for (float[] v : vectors)
		{
			bin.writeFloat(v[0]);
			bin.writeFloat(v[1]);
			bin.writeFloat(v[2]);
			bin.writeFloat(v[3]);
		}
		int byteLength = vectors.size() * 4 * 4;

		int bufferViewIndex = bufferViews.size();
		bufferViews.add(buildBufferView(byteOffset, byteLength, TARGET_ARRAY_BUFFER));

		JsonObject accessor = new JsonObject();
		accessor.addProperty("bufferView", bufferViewIndex);
		accessor.addProperty("componentType", COMPONENT_TYPE_FLOAT);
		accessor.addProperty("count", vectors.size());
		accessor.addProperty("type", "VEC4");
		int accessorIndex = accessors.size();
		accessors.add(accessor);
		return accessorIndex;
	}

	private static int writeVec2Accessor(java.util.List<float[]> vectors, BinaryBuffer bin, JsonArray bufferViews, JsonArray accessors)
	{
		bin.align4();
		int byteOffset = bin.size();
		for (float[] v : vectors)
		{
			bin.writeFloat(v[0]);
			bin.writeFloat(v[1]);
		}
		int byteLength = vectors.size() * 2 * 4;

		int bufferViewIndex = bufferViews.size();
		bufferViews.add(buildBufferView(byteOffset, byteLength, TARGET_ARRAY_BUFFER));

		JsonObject accessor = new JsonObject();
		accessor.addProperty("bufferView", bufferViewIndex);
		accessor.addProperty("componentType", COMPONENT_TYPE_FLOAT);
		accessor.addProperty("count", vectors.size());
		accessor.addProperty("type", "VEC2");
		int accessorIndex = accessors.size();
		accessors.add(accessor);
		return accessorIndex;
	}

	private static int writeIndicesAccessor(java.util.List<Integer> indices, boolean useIntIndices,
		BinaryBuffer bin, JsonArray bufferViews, JsonArray accessors)
	{
		bin.align4();
		int byteOffset = bin.size();
		for (int index : indices)
		{
			if (useIntIndices)
			{
				bin.writeUInt32(index);
			}
			else
			{
				bin.writeUInt16(index);
			}
		}
		int byteLength = indices.size() * (useIntIndices ? 4 : 2);

		int bufferViewIndex = bufferViews.size();
		bufferViews.add(buildBufferView(byteOffset, byteLength, TARGET_ELEMENT_ARRAY_BUFFER));

		JsonObject accessor = new JsonObject();
		accessor.addProperty("bufferView", bufferViewIndex);
		accessor.addProperty("componentType", useIntIndices ? COMPONENT_TYPE_UNSIGNED_INT : COMPONENT_TYPE_UNSIGNED_SHORT);
		accessor.addProperty("count", indices.size());
		accessor.addProperty("type", "SCALAR");
		int accessorIndex = accessors.size();
		accessors.add(accessor);
		return accessorIndex;
	}

	/** Embeds PNG bytes in the binary chunk and adds an {@code images} entry. Returns its index. */
	private static int writeImage(byte[] pngBytes, BinaryBuffer bin, JsonArray bufferViews, JsonArray imagesJson)
	{
		bin.align4();
		int byteOffset = bin.size();
		bin.writeBytes(pngBytes);
		int byteLength = pngBytes.length;

		int bufferViewIndex = bufferViews.size();
		bufferViews.add(buildImageBufferView(byteOffset, byteLength));

		JsonObject image = new JsonObject();
		image.addProperty("bufferView", bufferViewIndex);
		image.addProperty("mimeType", "image/png");
		int imageIndex = imagesJson.size();
		imagesJson.add(image);
		return imageIndex;
	}

	private static JsonObject buildBufferView(int byteOffset, int byteLength, int target)
	{
		JsonObject bufferView = new JsonObject();
		bufferView.addProperty("buffer", 0);
		bufferView.addProperty("byteOffset", byteOffset);
		bufferView.addProperty("byteLength", byteLength);
		bufferView.addProperty("target", target);
		return bufferView;
	}

	/** Like {@link #buildBufferView} but without {@code target}, which applies only to vertex and index buffers. */
	private static JsonObject buildImageBufferView(int byteOffset, int byteLength)
	{
		JsonObject bufferView = new JsonObject();
		bufferView.addProperty("buffer", 0);
		bufferView.addProperty("byteOffset", byteOffset);
		bufferView.addProperty("byteLength", byteLength);
		return bufferView;
	}

	private static JsonArray floatArray(float a, float b, float c)
	{
		JsonArray array = new JsonArray();
		array.add(a);
		array.add(b);
		array.add(c);
		return array;
	}

	/**
	 * Packs the chunks into a .glb: a 12-byte header (magic, version, total length), then each chunk as
	 * (length, type, data). Chunks are padded to 4-byte boundaries: JSON with spaces (0x20), binary
	 * with zeros, as the spec requires.
	 */
	private static byte[] assembleGlb(byte[] json, byte[] bin)
	{
		byte[] jsonPadded = padTo4((json), (byte) 0x20);
		byte[] binPadded = padTo4(bin, (byte) 0x00);

		int totalLength = GLB_HEADER_LENGTH
			+ CHUNK_HEADER_LENGTH + jsonPadded.length
			+ CHUNK_HEADER_LENGTH + binPadded.length;

		ByteBuffer buffer = ByteBuffer.allocate(totalLength).order(ByteOrder.LITTLE_ENDIAN);
		buffer.putInt(GLB_MAGIC);
		buffer.putInt(GLB_VERSION);
		buffer.putInt(totalLength);

		buffer.putInt(jsonPadded.length);
		buffer.putInt(CHUNK_TYPE_JSON);
		buffer.put(jsonPadded);

		buffer.putInt(binPadded.length);
		buffer.putInt(CHUNK_TYPE_BIN);
		buffer.put(binPadded);

		return buffer.array();
	}

	private static byte[] padTo4(byte[] data, byte padByte)
	{
		int remainder = data.length % 4;
		if (remainder == 0)
		{
			return data;
		}
		int padding = 4 - remainder;
		byte[] padded = new byte[data.length + padding];
		System.arraycopy(data, 0, padded, 0, data.length);
		for (int i = data.length; i < padded.length; i++)
		{
			padded[i] = padByte;
		}
		return padded;
	}

	/** Little-endian byte accumulator for the GLB binary chunk (glTF buffers are little-endian). */
	private static final class BinaryBuffer
	{
		private final ByteArrayOutputStream out = new ByteArrayOutputStream();

		int size()
		{
			return out.size();
		}

		void align4()
		{
			while (out.size() % 4 != 0)
			{
				out.write(0);
			}
		}

		void writeFloat(float v)
		{
			ByteBuffer b = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
			b.putFloat(v);
			out.writeBytes(b.array());
		}

		void writeUInt16(int v)
		{
			ByteBuffer b = ByteBuffer.allocate(2).order(ByteOrder.LITTLE_ENDIAN);
			b.putShort((short) v);
			out.writeBytes(b.array());
		}

		void writeUInt32(int v)
		{
			ByteBuffer b = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
			b.putInt(v);
			out.writeBytes(b.array());
		}

		void writeBytes(byte[] data)
		{
			out.write(data, 0, data.length);
		}

		byte[] toByteArray()
		{
			return out.toByteArray();
		}
	}
}

package io.myscape.plugin.modelexport;

/**
 * Converts OSRS packed-HSL face colors (from {@code Model#getFaceColors1/2/3}) to linear 0..1 RGB
 * for glTF vertex colors.
 *
 * <p>The HSL conversion is a port of RuneLite's {@code hslToRgb} shader
 * (net/runelite/client/plugins/gpu/hsl_to_rgb.glsl), so exported colors match how the game renders.
 *
 * <p>Packed format: 16 bits, {@code (hue << 10) | (sat << 7) | lightness}, with hue 0..63,
 * saturation 0..7 and lightness 0..127. For textured faces only the low 7 bits are meaningful: they
 * act as a 0..127 brightness multiplier on the texture (127 expands to white).
 *
 * <p>Color space: the shader output is display-ready sRGB, but glTF COLOR_0 is defined as linear and
 * viewers apply their own sRGB encode. Results are therefore passed through {@link #srgbToLinear} so
 * the displayed pixel matches the game. Embedded textures are ordinary sRGB images and need no change.
 */
final class HslColor
{
	private HslColor()
	{
	}

	/** Default {@code TextureProvider#getBrightness()}. Callers pass the live value when available. */
	static final double DEFAULT_BRIGHTNESS = 0.8;

	/**
	 * Untextured faces: converts a full packed HSL value. Mirrors {@code hslToRgb} in
	 * hsl_to_rgb.glsl, keeping its variable names for easy comparison. Returns {r, g, b}
	 * gamma-corrected by brightness, then decoded from sRGB to linear.
	 */
	static float[] toLinearRgb(int hsl, double brightness)
	{
		double hue = (hsl >> 10 & 0x3F) / 64.0 + 0.0078125;
		double sat = (hsl >> 7 & 0x7) / 8.0 + 0.0625;
		double lum = (hsl & 0x7F);

		double var11 = lum / 128.0;
		double r = var11;
		double g = var11;
		double b = var11;

		double var19 = var11 < 0.5 ? var11 * (1.0 + sat) : var11 + sat - var11 * sat;
		double var21 = 2.0 * var11 - var19;

		double var23 = hue + (1.0 / 3.0);
		if (var23 > 1.0)
		{
			var23 -= 1.0;
		}
		double var27 = hue - (1.0 / 3.0);
		if (var27 < 0.0)
		{
			var27 += 1.0;
		}

		r = channel(var23, var19, var21);
		g = channel(hue, var19, var21);
		b = channel(var27, var19, var21);

		return new float[]{
			srgbToLinear((float) Math.pow(clamp01(r), brightness)),
			srgbToLinear((float) Math.pow(clamp01(g), brightness)),
			srgbToLinear((float) Math.pow(clamp01(b), brightness)),
		};
	}

	/** The shader's piecewise hue formula, shared by all three channels (red: var23, green: hue, blue: var27). */
	private static double channel(double h, double var19, double var21)
	{
		if (6.0 * h < 1.0)
		{
			return var21 + (var19 - var21) * 6.0 * h;
		}
		if (2.0 * h < 1.0)
		{
			return var19;
		}
		if (3.0 * h < 2.0)
		{
			return var21 + (var19 - var21) * ((2.0 / 3.0) - h) * 6.0;
		}
		return var21;
	}

	/**
	 * Textured faces: the low 7 bits are a 0..127 brightness multiplier. 127 (fully lit) maps to
	 * white, leaving the texture unchanged. The brightness gamma applies as for untextured faces.
	 */
	static float[] textureLightnessToRgb(int hsl, double brightness)
	{
		float lightness = clamp01((hsl & 0x7F) / 127.0f);
		float v = srgbToLinear((float) Math.pow(lightness, brightness));
		return new float[]{v, v, v};
	}

	private static float clamp01(double v)
	{
		if (v < 0.0)
		{
			return 0f;
		}
		if (v > 1.0)
		{
			return 1f;
		}
		return (float) v;
	}

	/** Standard piecewise sRGB-to-linear decode. See the class doc for why it is applied. */
	private static float srgbToLinear(float c)
	{
		if (c <= 0.04045f)
		{
			return c / 12.92f;
		}
		return (float) Math.pow((c + 0.055) / 1.055, 2.4);
	}
}

package io.myscape.plugin.modelexport;

import java.util.ArrayList;
import java.util.List;

/** glTF-shaped result of {@link ModelMeshBuilder#build}, serialized by {@link GlbWriter}. */
final class MeshData
{
	/**
	 * A run of triangles sharing texture id, priority, bias and translucency. Priority and bias
	 * only split primitives so each carries its own glTF {@code extras}.
	 */
	static final class Primitive
	{
		/** OSRS texture id (from {@code Model#getFaceTextures}), or -1 if untextured. */
		final int textureId;
		/** True if the faces are partially transparent (alphaMode BLEND). */
		final boolean translucent;
		/** {@code Model#getFaceRenderPriorities()} value, unsigned 0-255 (0 if absent). */
		final int priority;
		/** {@code Model#getFaceBias()} value, unsigned 0-255 (0 if absent). */
		final int bias;
		/** Triangle corner indices into this mesh's vertex lists, three per triangle. */
		final List<Integer> indices = new ArrayList<>();

		Primitive(int textureId, boolean translucent, int priority, int bias)
		{
			this.textureId = textureId;
			this.translucent = translucent;
			this.priority = priority;
			this.bias = bias;
		}
	}

	/** Primitives in order of first appearance. */
	final List<Primitive> primitives = new ArrayList<>();

	/** Deduplicated {x, y, z} positions in glTF's right-handed axes (see ModelMeshBuilder.AXIS_SIGNS). */
	final List<float[]> positions = new ArrayList<>();
	/** Parallel to positions: linear {r, g, b, a}. */
	final List<float[]> colors = new ArrayList<>();
	/** Parallel to positions: {u, v}. Null for the whole list if the mesh has no textured faces. */
	List<float[]> uvs;

	/** Bounding box (required by the glTF POSITION accessor). Inverted until a vertex is added. */
	final float[] boundsMin = {Float.MAX_VALUE, Float.MAX_VALUE, Float.MAX_VALUE};
	final float[] boundsMax = {-Float.MAX_VALUE, -Float.MAX_VALUE, -Float.MAX_VALUE};

	void expandBounds(float x, float y, float z)
	{
		boundsMin[0] = Math.min(boundsMin[0], x);
		boundsMin[1] = Math.min(boundsMin[1], y);
		boundsMin[2] = Math.min(boundsMin[2], z);
		boundsMax[0] = Math.max(boundsMax[0], x);
		boundsMax[1] = Math.max(boundsMax[1], y);
		boundsMax[2] = Math.max(boundsMax[2], z);
	}
}

package io.myscape.plugin.modelexport;

import java.util.Collections;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Model;
import net.runelite.api.TextureProvider;

/**
 * Public entry point of this package: turns a live {@code Model} into a .glb byte array.
 * The other classes are package-private.
 */
@Slf4j
public final class ModelExporter
{
	private ModelExporter()
	{
	}

	/** Captures {@code model} at default brightness with no texture images. */
	public static byte[] captureGlb(Model model)
	{
		return GlbWriter.write(ModelMeshBuilder.build(model));
	}

	/** Captures {@code model} at the given brightness with no texture images. */
	public static byte[] captureGlb(Model model, double brightness)
	{
		return GlbWriter.write(ModelMeshBuilder.build(model, brightness));
	}

	/**
	 * Captures {@code model} as a self-contained .glb, embedding textures extracted from
	 * {@code textureProvider}. Must be called on the client thread.
	 *
	 * @param brightness      the client's {@code TextureProvider#getBrightness()}
	 * @param textureProvider may be null, in which case textures are omitted
	 */
	public static byte[] captureGlb(Model model, double brightness, TextureProvider textureProvider)
	{
		MeshData mesh = ModelMeshBuilder.build(model, brightness);
		Set<Integer> usedTextureIds = usedTextureIds(mesh);
		Map<Integer, byte[]> texturePngs = textureProvider != null
			? TextureExtractor.extractPngs(textureProvider, usedTextureIds)
			: Collections.emptyMap();

		// GlbWriter tags primitives whose texture is missing so the viewer can show a dim
		// fallback. Log the ids so the cause is diagnosable.
		if (textureProvider != null && texturePngs.size() < usedTextureIds.size())
		{
			Set<Integer> missing = new HashSet<>(usedTextureIds);
			missing.removeAll(texturePngs.keySet());
			log.warn("Character model export: {} of {} used texture(s) could not be extracted "
					+ "(ids {}); affected faces will render as a flat, untextured fallback.",
				missing.size(), usedTextureIds.size(), missing);
		}

		return GlbWriter.write(mesh, texturePngs);
	}

	/** Distinct texture ids used by {@code mesh}; -1 (untextured) is excluded. */
	private static Set<Integer> usedTextureIds(MeshData mesh)
	{
		Set<Integer> ids = new HashSet<>();
		for (MeshData.Primitive primitive : mesh.primitives)
		{
			if (primitive.textureId >= 0)
			{
				ids.add(primitive.textureId);
			}
		}
		return ids;
	}
}

package io.myscape.plugin.modelexport;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Model;

/**
 * Converts a live {@code net.runelite.api.Model} (the composited mesh from
 * {@code Renderable#getModel()}) into a {@link MeshData} for {@link GlbWriter}. All data is read from
 * the client's in-memory triangle arrays through RuneLite's public Model API.
 *
 * <p>The approach of re-packaging the runtime mesh as glTF is the one used by the RuneProfile plugin
 * (BSD-2-Clause); this is an independent implementation.
 *
 * <p>Render priority and bias are not part of the per-vertex dedup key. They are part of the primitive
 * key: each (textureId, priority, bias, translucent) group becomes its own primitive carrying
 * priority/bias as {@code extras}, so a viewer can reproduce the game's draw-order override for
 * near-coplanar faces such as capes.
 */
final class ModelMeshBuilder
{
	private ModelMeshBuilder()
	{
	}

	/**
	 * RuneLite uses X east, Y down, Z north; glTF is right-handed with Y up. Negating Y and Z is a
	 * 180-degree rotation about X, not a mirror, so triangle winding is preserved.
	 */
	private static final float[] AXIS_SIGNS = {1f, -1f, -1f};

	/** Third-corner color -1 means flat shading: the whole triangle uses corner 1's color. */
	private static final int FLAT_SHADED = -1;

	/**
	 * Third-corner color -2 means the game never draws the face. Both -1 and -2 decode as
	 * near-white packed HSL, so treating -2 as a color draws a stray white triangle (seen on fire and
	 * inferno capes). Such faces are skipped.
	 */
	private static final int HIDDEN_FACE = -2;

	static MeshData build(Model model)
	{
		return build(model, HslColor.DEFAULT_BRIGHTNESS);
	}

	static MeshData build(Model model, double brightness)
	{
		MeshData mesh = new MeshData();
		VertexBuffer vertexBuffer = new VertexBuffer(mesh);

		float[] vx = model.getVerticesX();
		float[] vy = model.getVerticesY();
		float[] vz = model.getVerticesZ();

		int[] i1 = model.getFaceIndices1();
		int[] i2 = model.getFaceIndices2();
		int[] i3 = model.getFaceIndices3();

		int[] c1 = model.getFaceColors1();
		int[] c2 = model.getFaceColors2();
		int[] c3 = model.getFaceColors3();

		short[] faceTextures = model.getFaceTextures();
		byte[] textureFaces = model.getTextureFaces();
		int[] tex1 = model.getTexIndices1();
		int[] tex2 = model.getTexIndices2();
		int[] tex3 = model.getTexIndices3();

		byte[] transparencies = model.getFaceTransparencies();
		byte[] priorities = model.getFaceRenderPriorities();
		byte[] biases = model.getFaceBias();

		boolean anyTextured = faceTextures != null;
		if (anyTextured)
		{
			mesh.uvs = new java.util.ArrayList<>();
		}

		// One primitive per (textureId, priority, bias, translucent) key, created lazily.
		Map<Long, MeshData.Primitive> primitivesByKey = new HashMap<>();

		int faceCount = model.getFaceCount();
		for (int face = 0; face < faceCount; face++)
		{
			if (c3[face] == HIDDEN_FACE)
			{
				// Never drawn by the game; see HIDDEN_FACE.
				continue;
			}

			int transparency = transparencies != null ? (transparencies[face] & 0xFF) : 0;
			if (transparency == 255)
			{
				// Fully transparent faces are never drawn by the client.
				continue;
			}
			boolean translucent = transparency > 0;
			float alpha = 1f - (transparency / 255f);

			int textureId = -1;
			boolean textured = false;
			if (faceTextures != null && faceTextures[face] != -1)
			{
				textureId = faceTextures[face] & 0xFFFF;
				textured = true;
			}

			int priority = priorities != null ? (priorities[face] & 0xFF) : 0;
			int bias = biases != null ? (biases[face] & 0xFF) : 0;

			// Pack the key into a long: textureId + 1 needs 17 bits (up to 65536); priority and bias
			// are one byte each.
			long key = ((long) (textureId + 1) << 17) | ((long) priority << 9) | ((long) bias << 1) | (translucent ? 1 : 0);
			MeshData.Primitive primitive = primitivesByKey.get(key);
			if (primitive == null)
			{
				primitive = new MeshData.Primitive(textureId, translucent, priority, bias);
				primitivesByKey.put(key, primitive);
				mesh.primitives.add(primitive);
			}

			int a = i1[face];
			int b = i2[face];
			int c = i3[face];

			float[] uvA = null;
			float[] uvB = null;
			float[] uvC = null;
			if (textured)
			{
				int refFace = textureFaces != null ? (textureFaces[face] & 0xFF) : face;
				int originIdx = tex1[refFace];
				int uEndIdx = tex2[refFace];
				int vEndIdx = tex3[refFace];
				float[] origin = {vx[originIdx], vy[originIdx], vz[originIdx]};
				float[] uEnd = {vx[uEndIdx], vy[uEndIdx], vz[uEndIdx]};
				float[] vEnd = {vx[vEndIdx], vy[vEndIdx], vz[vEndIdx]};
				uvA = computeFaceUv(origin, uEnd, vEnd, vx[a], vy[a], vz[a]);
				uvB = computeFaceUv(origin, uEnd, vEnd, vx[b], vy[b], vz[b]);
				uvC = computeFaceUv(origin, uEnd, vEnd, vx[c], vy[c], vz[c]);
			}

			// Flat-shaded faces use corner 1's color for all corners; see FLAT_SHADED.
			boolean flatShaded = c3[face] == FLAT_SHADED;
			int color2 = flatShaded ? c1[face] : c2[face];
			int color3 = flatShaded ? c1[face] : c3[face];

			float[] rgbA = textured
				? HslColor.textureLightnessToRgb(c1[face], brightness)
				: HslColor.toLinearRgb(c1[face], brightness);
			float[] rgbB = textured
				? HslColor.textureLightnessToRgb(color2, brightness)
				: HslColor.toLinearRgb(color2, brightness);
			float[] rgbC = textured
				? HslColor.textureLightnessToRgb(color3, brightness)
				: HslColor.toLinearRgb(color3, brightness);

			int ia = vertexBuffer.add(vx[a], vy[a], vz[a], rgbA, alpha, uvA);
			int ib = vertexBuffer.add(vx[b], vy[b], vz[b], rgbB, alpha, uvB);
			int ic = vertexBuffer.add(vx[c], vy[c], vz[c], rgbC, alpha, uvC);

			primitive.indices.add(ia);
			primitive.indices.add(ib);
			primitive.indices.add(ic);
		}

		return mesh;
	}

	/**
	 * Texture reference triangle projection. OSRS stores no per-vertex UVs: each textured face points
	 * at a reference triangle (origin, uEnd, vEnd) whose edges span the texture's (0,0)-(1,0)-(0,1)
	 * corners. A vertex's UV is its position expressed in the basis of those two edges. Uses cross
	 * products rather than a matrix inverse so points slightly off the triangle's plane still work.
	 */
	private static float[] computeFaceUv(float[] origin, float[] uEnd, float[] vEnd, float px, float py, float pz)
	{
		float[] e1 = sub(uEnd, origin);
		float[] e2 = sub(vEnd, origin);
		float[] f = {px - origin[0], py - origin[1], pz - origin[2]};

		float[] n = cross(e1, e2);
		float nDotN = dot(n, n);
		if (nDotN < 1e-12f)
		{
			// Degenerate reference triangle: fall back to (0,0).
			return new float[]{0f, 0f};
		}

		float s = dot(cross(f, e2), n) / nDotN;
		float t = dot(cross(e1, f), n) / nDotN;
		return new float[]{s, t};
	}

	private static float[] sub(float[] a, float[] b)
	{
		return new float[]{a[0] - b[0], a[1] - b[1], a[2] - b[2]};
	}

	private static float[] cross(float[] a, float[] b)
	{
		return new float[]{
			a[1] * b[2] - a[2] * b[1],
			a[2] * b[0] - a[0] * b[2],
			a[0] * b[1] - a[1] * b[0],
		};
	}

	private static float dot(float[] a, float[] b)
	{
		return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
	}

	/**
	 * Deduplicates face corners into glTF vertices keyed on (position, color+alpha, uv). The source
	 * vertex index is not used: faces sharing a model vertex may shade it differently (hard edge)
	 * and need separate glTF vertices.
	 */
	private static final class VertexBuffer
	{
		private final MeshData mesh;
		private final Map<String, Integer> indexByKey = new HashMap<>();

		VertexBuffer(MeshData mesh)
		{
			this.mesh = mesh;
		}

		int add(float x, float y, float z, float[] rgb, float alpha, float[] uv)
		{
			float gx = x * AXIS_SIGNS[0];
			float gy = y * AXIS_SIGNS[1];
			float gz = z * AXIS_SIGNS[2];

			String key = gx + "," + gy + "," + gz + "|"
				+ rgb[0] + "," + rgb[1] + "," + rgb[2] + "," + alpha + "|"
				+ (uv != null ? uv[0] + "," + uv[1] : "none");

			Integer existing = indexByKey.get(key);
			if (existing != null)
			{
				return existing;
			}

			int index = mesh.positions.size();
			mesh.positions.add(new float[]{gx, gy, gz});
			mesh.colors.add(new float[]{rgb[0], rgb[1], rgb[2], alpha});
			if (mesh.uvs != null)
			{
				mesh.uvs.add(uv != null ? uv : new float[]{0f, 0f});
			}
			mesh.expandBounds(gx, gy, gz);
			indexByKey.put(key, index);
			return index;
		}
	}
}

package io.myscape.plugin.modelexport;

import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.imageio.ImageIO;
import net.runelite.api.Texture;
import net.runelite.api.TextureProvider;

/**
 * Extracts texture pixels from the client's {@code TextureProvider} and encodes each as a PNG for
 * embedding in the GLB. Follows the GPU plugin's {@code TextureManager}.
 *
 * <p>{@code TextureProvider#load(int)} returns 128x128 packed {@code 0xRRGGBB} ints with no alpha;
 * 0 marks a transparent pixel rather than black, as in {@code TextureManager.convertPixels}.
 * Brightness is set to 1.0 around the load calls because the provider bakes its brightness into
 * the pixels, and the player's brightness is already applied per vertex (see
 * {@link HslColor#textureLightnessToRgb}).
 */
final class TextureExtractor
{
	private TextureExtractor()
	{
	}

	/** Texture width and height. Any {@code load()} result of another length is skipped, as in {@code TextureManager}. */
	private static final int TEXTURE_SIZE = 128;

	/**
	 * PNG-encodes every id in {@code textureIds} that {@code provider} can supply. Missing,
	 * unloaded or wrongly sized textures are skipped so the export still succeeds.
	 *
	 * @param provider   the client's texture provider; null returns an empty map
	 * @param textureIds texture ids referenced by the captured model
	 * @return texture id to PNG bytes, for the ids that could be extracted; never null
	 */
	static Map<Integer, byte[]> extractPngs(TextureProvider provider, Set<Integer> textureIds)
	{
		Map<Integer, byte[]> result = new HashMap<>();
		if (provider == null || textureIds.isEmpty())
		{
			return result;
		}

		Texture[] textures = provider.getTextures();
		if (textures == null)
		{
			return result;
		}

		// Brightness is pinned to 1.0 only while loading; see class doc.
		double savedBrightness = provider.getBrightness();
		provider.setBrightness(1.0d);
		try
		{
			for (int textureId : textureIds)
			{
				byte[] png = extractOne(provider, textures, textureId);
				if (png != null)
				{
					result.put(textureId, png);
				}
			}
		}
		finally
		{
			provider.setBrightness(savedBrightness);
		}
		return result;
	}

	private static byte[] extractOne(TextureProvider provider, Texture[] textures, int textureId)
	{
		if (textureId < 0 || textureId >= textures.length || textures[textureId] == null)
		{
			return null;
		}

		int[] srcPixels = provider.load(textureId);
		if (srcPixels == null || srcPixels.length != TEXTURE_SIZE * TEXTURE_SIZE)
		{
			return null;
		}

		BufferedImage image = new BufferedImage(TEXTURE_SIZE, TEXTURE_SIZE, BufferedImage.TYPE_INT_ARGB);
		int i = 0;
		for (int y = 0; y < TEXTURE_SIZE; y++)
		{
			for (int x = 0; x < TEXTURE_SIZE; x++)
			{
				int rgb = srcPixels[i++];
				// rgb == 0 marks a transparent pixel, not black.
				int argb = rgb == 0 ? 0 : (0xFF000000 | (rgb & 0xFFFFFF));
				image.setRGB(x, y, argb);
			}
		}

		try
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			ImageIO.write(image, "png", out);
			return out.toByteArray();
		}
		catch (IOException e)
		{
			// Not expected for an in-memory stream; skip this texture rather than abort the capture.
			return null;
		}
	}
}

package io.myscape.plugin;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * The `run` Gradle task's actual entry point (see build.gradle) -- NOT
 * `net.runelite.client.RuneLite` directly. RuneLite's own plugin
 * discovery only does two things: scan the `net.runelite.client.plugins`
 * package for core plugins, and load `.jar` files dropped in a
 * `sideloaded-plugins` directory. Neither one picks up a plugin class
 * sitting on the classpath in an arbitrary package like ours -- so
 * launching `RuneLite.main()` straight from the `run` task (which is
 * what this repo did initially) starts a perfectly normal client that
 * silently never loads MyscapePlugin at all: no crash, no log line, just
 * no icon in the sidebar. `ExternalPluginManager.loadBuiltin(...)`,
 * called before `RuneLite.main()` starts, is the actual mechanism
 * RuneLite provides for this -- it's the same pattern RuneLite's own
 * example-plugin template uses for its `run` task (see
 * ExamplePluginTest.java in runelite/example-plugin).
 */
public class MyscapePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(MyscapePlugin.class);
		RuneLite.main(args);
	}
}

package io.myscape.plugin.collectionlog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.any;
import static org.mockito.Mockito.anyInt;
import static org.mockito.Mockito.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

/**
 * Exercises {@link CollectionLogItemCapture} against a fully mocked
 * {@code Client} -- same reasoning as {@code
 * CollectionLogSchemaExporterTest}'s own doc: this environment has no
 * live game client, so a Mockito mock of the handful of {@code Client}
 * calls this class makes (menuAction/runScript/getVarbitValue/
 * getTickCount) is the only way to exercise its sequencing at all,
 * including the parts (the re-entrancy guard, the tick-settle buffer)
 * that only ever show up across several calls in a row.
 */
public class CollectionLogItemCaptureTest
{
	private static final int COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID = 4100;
	private static final int COLLECTION_LOG_SETUP_SCRIPT_ID = 7797;
	private static final int COLLECTION_LOG_INIT_SCRIPT_ID = 2240;
	private static final int UNRELATED_SCRIPT_ID = 1234;

	@Test
	public void triggersSearchToggleAndInitScriptOnOpen()
	{
		Client client = notOpenedFromAdventureLog();

		new CollectionLogItemCapture().onCollectionLogOpened(COLLECTION_LOG_SETUP_SCRIPT_ID, client);

		verify(client).menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		verify(client).runScript(COLLECTION_LOG_INIT_SCRIPT_ID);
	}

	@Test
	public void ignoresUnrelatedScriptIds()
	{
		Client client = mock(Client.class);
		CollectionLogItemCapture capture = new CollectionLogItemCapture();

		capture.onCollectionLogOpened(UNRELATED_SCRIPT_ID, client);
		capture.onScriptPreFired(UNRELATED_SCRIPT_ID, new Object[] { 0, 12922, 1 }, client);

		// Neither call should even need to check the adventure-log
		// varbit, since both bail out on the script id check first.
		verifyNoInteractions(client);
		assertTrue(capture.snapshotCapturedItems().isEmpty());
	}

	@Test
	public void doesNotRetriggerWhileACapturePassIsAlreadyInFlight()
	{
		Client client = notOpenedFromAdventureLog();
		CollectionLogItemCapture capture = new CollectionLogItemCapture();

		// The init script's own side effect is to re-fire the setup
		// script -- without the re-entrancy guard, this second call
		// would trigger a second search-toggle + init-script, which
		// would trigger a third, forever.
		capture.onCollectionLogOpened(COLLECTION_LOG_SETUP_SCRIPT_ID, client);
		capture.onCollectionLogOpened(COLLECTION_LOG_SETUP_SCRIPT_ID, client);

		verify(client, times(1)).runScript(COLLECTION_LOG_INIT_SCRIPT_ID);
	}

	@Test
	public void retriggersOnceThePreviousCapturePassHasSettled()
	{
		Client client = notOpenedFromAdventureLog();
		CollectionLogItemCapture capture = new CollectionLogItemCapture();

		capture.onCollectionLogOpened(COLLECTION_LOG_SETUP_SCRIPT_ID, client);
		capture.onScriptPreFired(COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID, new Object[] { 0, 12922, 1 }, client);

		when(client.getTickCount()).thenReturn(10, 13);
		// tick=10 is when the item above fired; tick=13 is 3 ticks
		// later, past the settle buffer, so this is where a pass is
		// decided to be finished and the guard resets.
		capture.onGameTick(client);
		capture.onGameTick(client);

		capture.onCollectionLogOpened(COLLECTION_LOG_SETUP_SCRIPT_ID, client);

		verify(client, times(2)).runScript(COLLECTION_LOG_INIT_SCRIPT_ID);
	}

	@Test
	public void capturesItemIdAndQuantityFromDelayedTransmit()
	{
		Client client = notOpenedFromAdventureLog();
		CollectionLogItemCapture capture = new CollectionLogItemCapture();

		capture.onScriptPreFired(COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID, new Object[] { 0, 12922, 3 }, client);

		Map<Integer, Integer> items = capture.snapshotCapturedItems();
		assertEquals(1, items.size());
		assertEquals(Integer.valueOf(3), items.get(12922));
	}

	@Test
	public void accumulatesMultipleItemsAcrossFirings()
	{
		Client client = notOpenedFromAdventureLog();
		CollectionLogItemCapture capture = new CollectionLogItemCapture();

		capture.onScriptPreFired(COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID, new Object[] { 0, 12922, 1 }, client);
		capture.onScriptPreFired(COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID, new Object[] { 0, 21295, 5 }, client);

		Map<Integer, Integer> items = capture.snapshotCapturedItems();
		assertEquals(2, items.size());
		assertEquals(Integer.valueOf(1), items.get(12922));
		assertEquals(Integer.valueOf(5), items.get(21295));
	}

	@Test
	public void skipsCaptureAndClearsWhenOpenedFromAdventureLog()
	{
		Client client = notOpenedFromAdventureLog();
		CollectionLogItemCapture capture = new CollectionLogItemCapture();
		capture.onScriptPreFired(COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID, new Object[] { 0, 12922, 1 }, client);
		assertFalse(capture.snapshotCapturedItems().isEmpty());

		Client adventureLogClient = openedFromAdventureLog();
		capture.onCollectionLogOpened(COLLECTION_LOG_SETUP_SCRIPT_ID, adventureLogClient);

		assertTrue(capture.snapshotCapturedItems().isEmpty());
		verify(adventureLogClient, never()).menuAction(
			anyInt(), anyInt(), any(MenuAction.class), anyInt(), anyInt(), anyString(), anyString());
	}

	@Test
	public void skipsItemCaptureWhenOpenedFromAdventureLog()
	{
		Client client = openedFromAdventureLog();
		CollectionLogItemCapture capture = new CollectionLogItemCapture();

		capture.onScriptPreFired(COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID, new Object[] { 0, 12922, 1 }, client);

		assertTrue(capture.snapshotCapturedItems().isEmpty());
	}

	@Test
	public void adventureLogVarbitChangedClearsCapturedItemsOnlyWhenOpen()
	{
		CollectionLogItemCapture capture = new CollectionLogItemCapture();
		Client client = notOpenedFromAdventureLog();
		capture.onScriptPreFired(COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID, new Object[] { 0, 12922, 1 }, client);
		assertFalse(capture.snapshotCapturedItems().isEmpty());

		capture.onAdventureLogVarbitChanged(client);
		assertFalse("varbit reporting closed should not clear anything", capture.snapshotCapturedItems().isEmpty());

		capture.onAdventureLogVarbitChanged(openedFromAdventureLog());
		assertTrue(capture.snapshotCapturedItems().isEmpty());
	}

	@Test
	public void gameTickReturnsFalseWithNoCapturePassInFlight()
	{
		Client client = mock(Client.class);
		CollectionLogItemCapture capture = new CollectionLogItemCapture();

		assertFalse(capture.onGameTick(client));
	}

	@Test
	public void gameTickSettlesOnlyAfterBufferElapses()
	{
		Client client = notOpenedFromAdventureLog();
		CollectionLogItemCapture capture = new CollectionLogItemCapture();

		when(client.getTickCount()).thenReturn(10);
		capture.onScriptPreFired(COLLECTION_DELAYED_TRANSMIT_SCRIPT_ID, new Object[] { 0, 12922, 1 }, client);

		when(client.getTickCount()).thenReturn(11);
		assertFalse("one tick after the item fired is still within the buffer", capture.onGameTick(client));

		when(client.getTickCount()).thenReturn(12);
		assertFalse("two ticks after is still within the buffer", capture.onGameTick(client));

		when(client.getTickCount()).thenReturn(13);
		assertTrue("three ticks after is past the buffer", capture.onGameTick(client));

		assertFalse("settling should only ever report true once per pass", capture.onGameTick(client));
	}

	private static Client notOpenedFromAdventureLog()
	{
		Client client = mock(Client.class);
		when(client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN)).thenReturn(0);
		return client;
	}

	private static Client openedFromAdventureLog()
	{
		Client client = mock(Client.class);
		when(client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN)).thenReturn(1);
		return client;
	}
}

package io.myscape.plugin.collectionlog;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import org.junit.Test;

/**
 * Exercises {@link CollectionLogSchemaExporter} against a fully mocked
 * {@code Client} -- this environment has no live game client, so a
 * Mockito mock of the struct/enum compositions it reads (matching this
 * codebase's existing TextureExtractorTest approach for {@code
 * TextureProvider}) is the only way to exercise the walk logic at all.
 * The fake data below deliberately covers a two-tab, two-page-per-tab
 * shape and includes one item id from {@code
 * PAGE_STRUCT_ITEM_ID_TO_WIDGET_ITEM_ID}'s own remap table, so the test
 * fails if either the tab/page/item structure or the remap is wired up
 * wrong.
 */
public class CollectionLogSchemaExporterTest
{
	@Test
	public void walksTabsPagesAndItemsInOrder()
	{
		Client client = mock(Client.class);

		// Tab 471 ("Bosses") -> page enum 9001 -> page structs 501, 502.
		stubTab(client, 471, "Bosses", 9001, new int[] { 501, 502 });
		stubPage(client, 501, "Zulrah", 9101, new int[] { 12922, 12923 });
		stubPage(client, 502, "Vorkath", 9102, new int[] { 21295 });

		// Tab 472 ("Raids") -> page enum 9002 -> page struct 503, whose
		// item enum includes 13273 (Abyssal Sire's "Unsired"), which the
		// remap table maps to widget id 25624 -- the one case this test
		// asserts on directly, so a broken or missing remap fails loudly
		// rather than only showing up as a mismatched item id downstream.
		stubTab(client, 472, "Raids", 9002, new int[] { 503 });
		stubPage(client, 503, "Theatre of Blood", 9103, new int[] { 13273, 22326 });

		// Tabs 473-475 (Clues, Minigames, Other) resolve to a page enum
		// that itself doesn't exist -- getEnum returns null, same as a
		// real client would for an id that doesn't resolve -- to check
		// that one bad tab is skipped entirely (not included with zero
		// pages, just left out) rather than throwing.
		stubTabWithMissingPageEnum(client, 473, "Clues", 9003);
		stubTabWithMissingPageEnum(client, 474, "Minigames", 9004);
		stubTabWithMissingPageEnum(client, 475, "Other", 9005);

		CollectionLogSchema schema = CollectionLogSchemaExporter.export(client);

		List<CollectionLogSchema.Tab> tabs = schema.getTabs();
		assertEquals(2, tabs.size());

		CollectionLogSchema.Tab bosses = tabs.get(0);
		assertEquals("Bosses", bosses.getName());
		assertEquals(2, bosses.getPages().size());

		CollectionLogSchema.Page zulrah = bosses.getPages().get(0);
		assertEquals("Zulrah", zulrah.getName());
		assertEquals(List.of(12922, 12923), zulrah.getItemIds());

		CollectionLogSchema.Page vorkath = bosses.getPages().get(1);
		assertEquals("Vorkath", vorkath.getName());
		assertEquals(List.of(21295), vorkath.getItemIds());

		CollectionLogSchema.Tab raids = tabs.get(1);
		assertEquals("Raids", raids.getName());
		CollectionLogSchema.Page tob = raids.getPages().get(0);
		assertEquals("Theatre of Blood", tob.getName());
		// 13273 remapped to 25624 (Unsired); 22326 passed through as-is.
		assertEquals(List.of(25624, 22326), tob.getItemIds());
	}

	private static void stubTab(Client client, int tabStructId, String tabName, int pageEnumId, int[] pageStructIds)
	{
		StructComposition tabStruct = mock(StructComposition.class);
		when(tabStruct.getStringValue(682)).thenReturn(tabName);
		when(tabStruct.getIntValue(683)).thenReturn(pageEnumId);
		when(client.getStructComposition(tabStructId)).thenReturn(tabStruct);

		EnumComposition pageEnum = mock(EnumComposition.class);
		when(pageEnum.getIntVals()).thenReturn(pageStructIds);
		when(client.getEnum(pageEnumId)).thenReturn(pageEnum);
	}

	private static void stubTabWithMissingPageEnum(Client client, int tabStructId, String tabName, int pageEnumId)
	{
		StructComposition tabStruct = mock(StructComposition.class);
		when(tabStruct.getStringValue(682)).thenReturn(tabName);
		when(tabStruct.getIntValue(683)).thenReturn(pageEnumId);
		when(client.getStructComposition(tabStructId)).thenReturn(tabStruct);
		when(client.getEnum(pageEnumId)).thenReturn(null);
	}

	private static void stubPage(Client client, int pageStructId, String pageName, int itemsEnumId, int[] itemIds)
	{
		StructComposition pageStruct = mock(StructComposition.class);
		when(pageStruct.getStringValue(689)).thenReturn(pageName);
		when(pageStruct.getIntValue(690)).thenReturn(itemsEnumId);
		when(client.getStructComposition(pageStructId)).thenReturn(pageStruct);

		EnumComposition itemsEnum = mock(EnumComposition.class);
		when(itemsEnum.getIntVals()).thenReturn(itemIds);
		when(client.getEnum(itemsEnumId)).thenReturn(itemsEnum);
	}
}

package io.myscape.plugin.modelexport;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import net.runelite.api.Model;

/**
 * A synthetic {@code net.runelite.api.Model} for testing
 * {@link ModelMeshBuilder} without a live game client -- this
 * environment has no way to actually run RuneLite/log into OSRS, so
 * this is the only way to exercise the exporter's own logic at all.
 * Built as a {@link Proxy} over the real {@code Model} interface
 * (rather than a hand-written class implementing it directly) because
 * Model pulls in a long tail of methods from Mesh/Renderable/Node this
 * builder never touches (draw calls, scene bookkeeping, linked-list
 * Node pointers, ...) -- a real implementing class would need a stub
 * for every one of them just to compile, where a Proxy only needs
 * explicit handling for the handful this test actually cares about;
 * anything else falls through to a type-appropriate zero/false/null
 * default, same approach RuneProfile's own FakeModel test double
 * (which this mirrors the shape of, independently written) uses for
 * the same reason.
 */
final class FakeModel
{
	private FakeModel()
	{
	}

	static Builder builder()
	{
		return new Builder();
	}

	static final class Builder
	{
		private int faceCount;
		private float[] vx = {};
		private float[] vy = {};
		private float[] vz = {};
		private int[] i1 = {};
		private int[] i2 = {};
		private int[] i3 = {};
		private int[] c1 = {};
		private int[] c2 = {};
		private int[] c3 = {};
		private short[] faceTextures;
		private byte[] textureFaces;
		private int[] tex1 = {};
		private int[] tex2 = {};
		private int[] tex3 = {};
		private byte[] transparencies;
		private byte[] renderPriorities;
		private byte[] biases;

		Builder faceCount(int faceCount)
		{
			this.faceCount = faceCount;
			return this;
		}

		Builder vertices(float[] vx, float[] vy, float[] vz)
		{
			this.vx = vx;
			this.vy = vy;
			this.vz = vz;
			return this;
		}

		Builder faceIndices(int[] i1, int[] i2, int[] i3)
		{
			this.i1 = i1;
			this.i2 = i2;
			this.i3 = i3;
			return this;
		}

		Builder faceColors(int[] c1, int[] c2, int[] c3)
		{
			this.c1 = c1;
			this.c2 = c2;
			this.c3 = c3;
			return this;
		}

		Builder faceTextures(short[] faceTextures)
		{
			this.faceTextures = faceTextures;
			return this;
		}

		Builder textureTriangles(byte[] textureFaces, int[] tex1, int[] tex2, int[] tex3)
		{
			this.textureFaces = textureFaces;
			this.tex1 = tex1;
			this.tex2 = tex2;
			this.tex3 = tex3;
			return this;
		}

		Builder faceTransparencies(byte[] transparencies)
		{
			this.transparencies = transparencies;
			return this;
		}

		Builder faceRenderPriorities(byte[] renderPriorities)
		{
			this.renderPriorities = renderPriorities;
			return this;
		}

		Builder faceBias(byte[] biases)
		{
			this.biases = biases;
			return this;
		}

		Model build()
		{
			InvocationHandler handler = (proxy, method, args) -> {
				switch (method.getName())
				{
					case "getFaceCount":
						return faceCount;
					case "getVerticesCount":
						return vx.length;
					case "getVerticesX":
						return vx;
					case "getVerticesY":
						return vy;
					case "getVerticesZ":
						return vz;
					case "getFaceIndices1":
						return i1;
					case "getFaceIndices2":
						return i2;
					case "getFaceIndices3":
						return i3;
					case "getFaceColors1":
						return c1;
					case "getFaceColors2":
						return c2;
					case "getFaceColors3":
						return c3;
					case "getFaceTextures":
						return faceTextures;
					case "getTextureFaces":
						return textureFaces;
					case "getTexIndices1":
						return tex1;
					case "getTexIndices2":
						return tex2;
					case "getTexIndices3":
						return tex3;
					case "getFaceTransparencies":
						return transparencies;
					case "getFaceRenderPriorities":
						return renderPriorities;
					case "getFaceBias":
						return biases;
					case "equals":
						return proxy == args[0];
					case "hashCode":
						return System.identityHashCode(proxy);
					case "toString":
						return "FakeModel";
					default:
						return defaultValueFor(method.getReturnType());
				}
			};
			return (Model) Proxy.newProxyInstance(
				FakeModel.class.getClassLoader(),
				new Class<?>[]{Model.class},
				handler);
		}

		private static Object defaultValueFor(Class<?> returnType)
		{
			if (!returnType.isPrimitive())
			{
				return null;
			}
			if (returnType == boolean.class)
			{
				return false;
			}
			if (returnType == void.class)
			{
				return null;
			}
			// Every other primitive (int, byte, short, long, float,
			// double, char) widens from 0 without a cast, which is all
			// reflection's own auto(un)boxing needs here.
			return 0;
		}
	}
}

package io.myscape.plugin.modelexport;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;
import net.runelite.api.Model;
import org.junit.Test;

/**
 * Checks the raw GLB container bytes {@link GlbWriter} produces
 * (header, chunk framing, 4-byte alignment) against the glTF 2.0 spec
 * by hand-parsing them back out -- the same level of "read the actual
 * bytes, don't trust the code that wrote them" this whole codebase's
 * conventions call for. Also writes a real .glb to disk for an
 * external, independent glTF validator to check (see this plugin's own
 * commit notes for that run) -- structurally valid framing isn't the
 * same as a spec-conformant document overall, so both checks matter.
 */
public class GlbWriterTest
{
	@Test
	public void producesWellFormedGlbContainer() throws IOException
	{
		Model model = buildMixedSyntheticModel();
		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);
		byte[] glb = GlbWriter.write(mesh);

		ByteBuffer buffer = ByteBuffer.wrap(glb).order(ByteOrder.LITTLE_ENDIAN);
		int magic = buffer.getInt();
		int version = buffer.getInt();
		int totalLength = buffer.getInt();

		assertEquals("magic == ASCII 'glTF' little-endian", 0x46546C67, magic);
		assertEquals(2, version);
		assertEquals("declared total length matches actual byte count", glb.length, totalLength);
		assertEquals("whole file is 4-byte aligned per spec", 0, glb.length % 4);

		int jsonChunkLength = buffer.getInt();
		int jsonChunkType = buffer.getInt();
		assertEquals("first chunk is JSON", 0x4E4F534A, jsonChunkType);
		assertEquals("chunk length itself is 4-byte aligned", 0, jsonChunkLength % 4);
		byte[] jsonBytes = new byte[jsonChunkLength];
		buffer.get(jsonBytes);
		String json = new String(jsonBytes, java.nio.charset.StandardCharsets.UTF_8);
		assertTrue("padded with spaces, not nulls, per spec", json.trim().endsWith("}"));
		assertTrue(json.contains("\"POSITION\""));
		assertTrue(json.contains("KHR_materials_unlit"));

		int binChunkLength = buffer.getInt();
		int binChunkType = buffer.getInt();
		assertEquals("second chunk is BIN", 0x004E4942, binChunkType);
		assertEquals(0, binChunkLength % 4);
		byte[] binBytes = new byte[binChunkLength];
		buffer.get(binBytes);

		assertEquals("no trailing bytes after the two chunks", 0, buffer.remaining());

		// Write a real file so it can be checked with an independent,
		// off-the-shelf glTF validator (e.g. pygltflib) -- this test
		// only confirms MY OWN reading of the container matches what I
		// wrote, which would happily agree with itself even if both
		// were wrong about the actual spec.
		File outFile = new File(System.getProperty("java.io.tmpdir"), "myscape-model-export-test.glb");
		try (FileOutputStream fos = new FileOutputStream(outFile))
		{
			fos.write(glb);
		}
		System.out.println("Wrote test GLB to: " + outFile.getAbsolutePath());
	}

	@Test
	public void withNoTexturePngsSuppliedEveryMaterialStaysUntextured()
	{
		Model model = buildMixedSyntheticModel();
		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		// The textured triangle's own texture id (3) genuinely has no
		// entry in this map -- e.g. a synthetic test mesh, or a real
		// capture where TextureExtractor couldn't pull that one id --
		// so every material must fall back to the old flat-vertex-color
		// behavior rather than reference a texture that doesn't exist.
		ParsedGlb parsed = ParsedGlb.parse(GlbWriter.write(mesh, new HashMap<>()));

		assertFalse("no images embedded at all", parsed.json.has("images"));
		for (JsonElement materialEl : parsed.json.getAsJsonArray("materials"))
		{
			JsonObject pbr = materialEl.getAsJsonObject().getAsJsonObject("pbrMetallicRoughness");
			assertFalse("no material references a texture that was never supplied",
				pbr.has("baseColorTexture"));
		}

		JsonArray primitivesJson = parsed.json.getAsJsonArray("meshes").get(0).getAsJsonObject()
			.getAsJsonArray("primitives");
		boolean sawMissingTextureTrue = false;
		for (JsonElement primEl : primitivesJson)
		{
			if (primEl.getAsJsonObject().getAsJsonObject("extras").get("missingTexture").getAsBoolean())
			{
				sawMissingTextureTrue = true;
			}
		}
		assertTrue("the one primitive that actually wanted a texture is flagged missing", sawMissingTextureTrue);
	}

	@Test
	public void embedsSuppliedTexturePngAndReferencesItFromTheTexturedMaterialOnly() throws IOException
	{
		Model model = buildMixedSyntheticModel();
		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		byte[] png = encodeTinyPng(0xFF00FF); // a small, recognizable magenta square
		Map<Integer, byte[]> texturePngs = new HashMap<>();
		texturePngs.put(3, png); // matches buildMixedSyntheticModel's own textureId

		ParsedGlb parsed = ParsedGlb.parse(GlbWriter.write(mesh, texturePngs));

		JsonArray images = parsed.json.getAsJsonArray("images");
		assertEquals("exactly one distinct texture id was supplied -> one image", 1, images.size());
		JsonObject image = images.get(0).getAsJsonObject();
		assertEquals("image/png", image.get("mimeType").getAsString());

		JsonArray samplers = parsed.json.getAsJsonArray("samplers");
		assertEquals(1, samplers.size());
		assertEquals("OSRS textures sample nearest, not smoothed -- see GlbWriter's own doc",
			9728, samplers.get(0).getAsJsonObject().get("magFilter").getAsInt());

		// Read the embedded image bytes back out of the binary chunk
		// (not just checking the JSON says an image exists) and confirm
		// they decode to a real PNG matching what was supplied --
		// exactly the "read the actual bytes back" standard the rest of
		// this test class already holds itself to.
		JsonObject bufferView = parsed.json.getAsJsonArray("bufferViews")
			.get(image.get("bufferView").getAsInt()).getAsJsonObject();
		int offset = bufferView.get("byteOffset").getAsInt();
		int length = bufferView.get("byteLength").getAsInt();
		assertFalse("an image bufferView must not claim a vertex/index buffer target",
			bufferView.has("target"));
		byte[] embeddedPng = new byte[length];
		System.arraycopy(parsed.bin, offset, embeddedPng, 0, length);
		assertArrayEquals("embedded image bytes are byte-for-byte the PNG that was supplied, not re-encoded",
			png, embeddedPng);
		BufferedImage decoded = ImageIO.read(new ByteArrayInputStream(embeddedPng));
		assertEquals(0xFFFF00FF, decoded.getRGB(0, 0));

		JsonArray materials = parsed.json.getAsJsonArray("materials");
		int taggedTextured = 0;
		int taggedUntextured = 0;
		for (JsonElement materialEl : materials)
		{
			JsonObject pbr = materialEl.getAsJsonObject().getAsJsonObject("pbrMetallicRoughness");
			if (pbr.has("baseColorTexture"))
			{
				taggedTextured++;
				assertEquals(0, pbr.getAsJsonObject("baseColorTexture").get("index").getAsInt());
				JsonArray baseColorFactor = pbr.getAsJsonArray("baseColorFactor");
				assertEquals("baseColorFactor stays white -- COLOR_0 and the texture do all the work",
					1.0f, baseColorFactor.get(0).getAsFloat(), 0f);
			}
			else
			{
				taggedUntextured++;
			}
		}
		assertEquals("exactly one material (the textured triangle's) references the image", 1, taggedTextured);
		assertTrue("the untextured/translucent triangles' own materials are unaffected", taggedUntextured >= 1);
	}

	@Test
	public void twoPrimitivesSharingOneTextureIdEmbedOnlyOneImage() throws IOException
	{
		// One opaque and one translucent triangle, both textured with
		// the same id -- two different (textureId, translucent) keys,
		// so ModelMeshBuilder puts them in two different primitives
		// (see MeshData.Primitive's own doc), but they should still
		// only need the one underlying texture image embedded once.
		short textureId = 5;
		int hsl = 127;
		Model model = FakeModel.builder()
			.faceCount(2)
			.vertices(
				new float[]{0f, 1f, 0f, 0f, 1f, 0f},
				new float[]{0f, 0f, 1f, 0f, 0f, 1f},
				new float[]{0f, 0f, 0f, 0f, 0f, 0f})
			.faceIndices(new int[]{0, 0}, new int[]{1, 1}, new int[]{2, 2})
			.faceColors(new int[]{hsl, hsl}, new int[]{hsl, hsl}, new int[]{hsl, hsl})
			.faceTextures(new short[]{textureId, textureId})
			.textureTriangles(new byte[]{0, 1}, new int[]{0, 0}, new int[]{1, 1}, new int[]{2, 2})
			.faceTransparencies(new byte[]{0, 64})
			.build();
		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);
		assertEquals("opaque-textured and translucent-textured are two separate primitives",
			2, mesh.primitives.size());

		Map<Integer, byte[]> texturePngs = new HashMap<>();
		texturePngs.put((int) textureId, encodeTinyPng(0x00FF00));

		ParsedGlb parsed = ParsedGlb.parse(GlbWriter.write(mesh, texturePngs));

		assertEquals("both primitives share the same underlying texture id -> one image, not two",
			1, parsed.json.getAsJsonArray("images").size());
		assertEquals(1, parsed.json.getAsJsonArray("textures").size());
		assertEquals("both materials reference the same (only) texture", 2,
			parsed.json.getAsJsonArray("materials").size());
	}

	@Test
	public void primitivesCarryTheirOwnRenderPriorityAndBiasAsExtras()
	{
		int hsl = packHsl(0, 0, 64);
		Model model = FakeModel.builder()
			.faceCount(2)
			.vertices(
				new float[]{0f, 1f, 0f, 5f, 6f, 5f},
				new float[]{0f, 0f, 1f, 5f, 5f, 6f},
				new float[]{0f, 0f, 0f, 5f, 5f, 5f})
			.faceIndices(new int[]{0, 3}, new int[]{1, 4}, new int[]{2, 5})
			.faceColors(new int[]{hsl, hsl}, new int[]{hsl, hsl}, new int[]{hsl, hsl})
			.faceRenderPriorities(new byte[]{2, 9})
			.faceBias(new byte[]{0, 3})
			.build();
		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);
		assertEquals(2, mesh.primitives.size());

		ParsedGlb parsed = ParsedGlb.parse(GlbWriter.write(mesh));

		JsonArray primitivesJson = parsed.json.getAsJsonArray("meshes").get(0).getAsJsonObject()
			.getAsJsonArray("primitives");
		assertEquals(2, primitivesJson.size());
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (JsonElement primEl : primitivesJson)
		{
			JsonObject extras = primEl.getAsJsonObject().getAsJsonObject("extras");
			assertTrue("every primitive carries its own osrsPriority/osrsBias extras", extras != null);
			seen.add(extras.get("osrsPriority").getAsInt() + "," + extras.get("osrsBias").getAsInt());
		}
		assertTrue(seen.contains("2,0"));
		assertTrue(seen.contains("9,3"));
	}

	@Test
	public void missingTextureIsFlaggedInExtras_suppliedTextureIsNot() throws IOException
	{
		// buildMixedSyntheticModel's own textured triangle uses texture id
		// 3 -- supplying a PNG for a DIFFERENT id (7) means primitive 3
		// still genuinely wants a texture it doesn't have, the exact
		// real-capture scenario (TextureExtractor pulled some of a
		// model's textures but not this one) missingTexture exists to
		// flag, distinct from a primitive that was never textured at all.
		Model model = buildMixedSyntheticModel();
		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		Map<Integer, byte[]> texturePngs = new HashMap<>();
		texturePngs.put(7, encodeTinyPng(0x00FF00));

		ParsedGlb parsed = ParsedGlb.parse(GlbWriter.write(mesh, texturePngs));

		JsonArray primitivesJson = parsed.json.getAsJsonArray("meshes").get(0).getAsJsonObject()
			.getAsJsonArray("primitives");
		boolean sawMissingTextureTrue = false;
		for (JsonElement primEl : primitivesJson)
		{
			JsonObject extras = primEl.getAsJsonObject().getAsJsonObject("extras");
			boolean missingTexture = extras.get("missingTexture").getAsBoolean();
			if (missingTexture)
			{
				sawMissingTextureTrue = true;
			}
			else
			{
				// An untextured primitive (textureId == -1) is correctly
				// NOT flagged -- it never wanted a texture, so nothing is
				// actually missing for it.
			}
		}
		assertTrue("the primitive that wanted texture id 3 (never supplied) is flagged", sawMissingTextureTrue);
	}

	@Test
	public void suppliedTextureIsNotFlaggedAsMissing() throws IOException
	{
		Model model = buildMixedSyntheticModel();
		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		Map<Integer, byte[]> texturePngs = new HashMap<>();
		texturePngs.put(3, encodeTinyPng(0xFF00FF)); // matches buildMixedSyntheticModel's own textureId

		ParsedGlb parsed = ParsedGlb.parse(GlbWriter.write(mesh, texturePngs));

		JsonArray primitivesJson = parsed.json.getAsJsonArray("meshes").get(0).getAsJsonObject()
			.getAsJsonArray("primitives");
		for (JsonElement primEl : primitivesJson)
		{
			JsonObject extras = primEl.getAsJsonObject().getAsJsonObject("extras");
			assertFalse("every primitive's own texture need was satisfied -- none should be flagged",
				extras.get("missingTexture").getAsBoolean());
		}
	}

	/** A small mixed model exercising every branch GlbWriter has to
	 * handle at once: an untextured opaque triangle, a textured opaque
	 * triangle (axis-aligned reference triangle, same as
	 * ModelMeshBuilderTest's own UV case), and a partially-transparent
	 * untextured triangle -- so the resulting file has >1 primitive,
	 * >1 material, and a real TEXCOORD_0 accessor to check. */
	private static Model buildMixedSyntheticModel()
	{
		int plainHsl = packHsl(20, 5, 80);
		int litHsl = 127;
		short textureId = 3;

		return FakeModel.builder()
			.faceCount(3)
			.vertices(
				new float[]{0f, 1f, 0f, 0f, 1f, 0f, 10f, 11f, 10f},
				new float[]{0f, 0f, 1f, 0f, 0f, 1f, 10f, 10f, 11f},
				new float[]{0f, 0f, 0f, 0f, 0f, 0f, 10f, 10f, 10f})
			.faceIndices(new int[]{0, 3, 6}, new int[]{1, 4, 7}, new int[]{2, 5, 8})
			.faceColors(
				new int[]{plainHsl, litHsl, plainHsl},
				new int[]{plainHsl, litHsl, plainHsl},
				new int[]{plainHsl, litHsl, plainHsl})
			.faceTextures(new short[]{-1, textureId, -1})
			.textureTriangles(new byte[]{0, 1, 0}, new int[]{0, 3, 0}, new int[]{1, 4, 1}, new int[]{2, 5, 2})
			.faceTransparencies(new byte[]{0, 0, 64})
			.build();
	}

	private static int packHsl(int hue, int sat, int lightness)
	{
		return (hue << 10) | (sat << 7) | lightness;
	}

	private static byte[] encodeTinyPng(int rgb) throws IOException
	{
		BufferedImage image = new BufferedImage(4, 4, BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < 4; y++)
		{
			for (int x = 0; x < 4; x++)
			{
				image.setRGB(x, y, 0xFF000000 | rgb);
			}
		}
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		ImageIO.write(image, "png", out);
		return out.toByteArray();
	}

	/** Hand-parses a .glb's two chunks into a JSON root and the raw
	 * binary chunk bytes, the same header/chunk framing {@link
	 * #producesWellFormedGlbContainer} checks byte-by-byte -- factored
	 * out here so the tests that care about JSON *content* (materials,
	 * images, samplers) don't have to repeat that framing logic, while
	 * the framing itself stays checked exactly once, explicitly, above. */
	private static final class ParsedGlb
	{
		final JsonObject json;
		final byte[] bin;

		private ParsedGlb(JsonObject json, byte[] bin)
		{
			this.json = json;
			this.bin = bin;
		}

		static ParsedGlb parse(byte[] glb)
		{
			ByteBuffer buffer = ByteBuffer.wrap(glb).order(ByteOrder.LITTLE_ENDIAN);
			buffer.getInt(); // magic
			buffer.getInt(); // version
			buffer.getInt(); // totalLength

			int jsonChunkLength = buffer.getInt();
			buffer.getInt(); // json chunk type
			byte[] jsonBytes = new byte[jsonChunkLength];
			buffer.get(jsonBytes);
			String json = new String(jsonBytes, java.nio.charset.StandardCharsets.UTF_8);

			int binChunkLength = buffer.getInt();
			buffer.getInt(); // bin chunk type
			byte[] binBytes = new byte[binChunkLength];
			buffer.get(binBytes);

			// The old instance-method form, not the newer static
			// JsonParser.parseString -- the Gson version this plugin
			// already depends on transitively via the client jar
			// predates that static method.
			return new ParsedGlb(new JsonParser().parse(json).getAsJsonObject(), binBytes);
		}
	}
}

package io.myscape.plugin.modelexport;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * Checks the sRGB linearization added to {@link HslColor} after a real
 * in-game comparison showed exported models too washed out / low on
 * contrast -- see that class's own top-of-file doc for the full
 * diagnosis (three.js's GLTFLoader takes COLOR_0 as already linear on
 * faith and re-encodes it for display; handing it an already display-
 * space value double-encodes it). The core property under test: a
 * standard sRGB *encode* applied on top of what this class now returns
 * must reproduce the exact display-space value the client's own shader
 * would have shown -- i.e. encode(HslColor's output) == the old,
 * pre-fix value -- since that round trip is the entire point of the
 * fix and is exactly what a spec-correct glTF viewer does at render
 * time.
 */
public class HslColorTest
{
	private static final float EPS = 1e-4f;

	@Test
	public void textureLightnessFullyLit_staysExactlyWhite()
	{
		// 127 (fully lit) is a fixed point of the sRGB curve at both
		// ends (0 -> 0, 1 -> 1 always), so this boundary case is
		// unaffected by the fix and should still be exactly white --
		// matching HslColor's own documented "127 expands to white"
		// contract that ModelMeshBuilderTest also relies on.
		float[] rgb = HslColor.textureLightnessToRgb(127, HslColor.DEFAULT_BRIGHTNESS);
		assertEquals(1f, rgb[0], EPS);
		assertEquals(1f, rgb[1], EPS);
		assertEquals(1f, rgb[2], EPS);
	}

	@Test
	public void textureLightnessZero_staysExactlyBlack()
	{
		float[] rgb = HslColor.textureLightnessToRgb(0, HslColor.DEFAULT_BRIGHTNESS);
		assertEquals(0f, rgb[0], EPS);
		assertEquals(0f, rgb[1], EPS);
		assertEquals(0f, rgb[2], EPS);
	}

	@Test
	public void textureLightness_roundTripsThroughStandardSrgbEncodeBackToTheDisplayValue()
	{
		// A handful of non-boundary lightness/brightness combinations --
		// each checks that re-applying the standard sRGB OETF (the exact
		// inverse of the EOTF HslColor now applies) on top of HslColor's
		// new output reproduces the old, pre-fix "pow(lightness, brightness)"
		// display-space value HslColor's own doc says the client's shader
		// actually puts on screen.
		int[] lightnesses = {1, 32, 64, 90, 120, 126};
		double[] brightnesses = {0.5, HslColor.DEFAULT_BRIGHTNESS, 1.0};

		for (int lightness : lightnesses)
		{
			for (double brightness : brightnesses)
			{
				float displayValue = (float) Math.pow(lightness / 127.0, brightness);
				float linear = HslColor.textureLightnessToRgb(lightness, brightness)[0];
				assertEquals(
					"lightness=" + lightness + " brightness=" + brightness,
					displayValue, srgbEncode(linear), 1e-3f);
			}
		}
	}

	@Test
	public void textureLightness_isMonotonicallyIncreasing()
	{
		// The fix recalibrates the space these values live in, but must
		// not reorder them relative to each other -- a brighter source
		// lightness must still come out brighter after the fix, or every
		// face's shading relative to its neighbors would be scrambled.
		float previous = -1f;
		for (int lightness = 0; lightness <= 127; lightness++)
		{
			float v = HslColor.textureLightnessToRgb(lightness, HslColor.DEFAULT_BRIGHTNESS)[0];
			assertTrue("lightness " + lightness + " should be >= the previous step", v >= previous);
			previous = v;
		}
	}

	@Test
	public void toLinearRgb_everyChannelStaysInZeroToOneRange()
	{
		// Sweep every hue/sat/lightness combination is overkill, but a
		// representative spread across the packed HSL space catches a
		// clamp/overflow bug in either the existing HSL math or the new
		// sRGB step wrapped around it.
		for (int hue = 0; hue < 64; hue += 9)
		{
			for (int sat = 0; sat < 8; sat += 3)
			{
				for (int lightness = 0; lightness < 128; lightness += 17)
				{
					int hsl = (hue << 10) | (sat << 7) | lightness;
					float[] rgb = HslColor.toLinearRgb(hsl, HslColor.DEFAULT_BRIGHTNESS);
					for (float channel : rgb)
					{
						assertTrue("hsl=" + hsl + " channel=" + channel, channel >= 0f && channel <= 1f);
					}
				}
			}
		}
	}

	/** The standard sRGB OETF (the "encode from linear" direction) --
	 * the exact inverse of the private HslColor#srgbToLinear this test
	 * is checking against, reimplemented here rather than reflectively
	 * reaching into HslColor's own private method, so the test is an
	 * independent check of the round trip rather than the same code
	 * calling itself. */
	private static float srgbEncode(float linear)
	{
		if (linear <= 0.0031308f)
		{
			return linear * 12.92f;
		}
		return (float) (1.055 * Math.pow(linear, 1.0 / 2.4) - 0.055);
	}
}

package io.myscape.plugin.modelexport;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import net.runelite.api.Model;
import org.junit.Test;

public class ModelMeshBuilderTest
{
	private static final float EPS = 1e-4f;

	@Test
	public void singleUntexturedFace_onePrimitive_threeVertices()
	{
		// A flat, untextured triangle: (0,0,0), (1,0,0), (0,1,0) in
		// RuneLite's own X-east/Y-down/Z-north space, all sharing a
		// single flat-shaded HSL color -- the simplest possible input.
		int hsl = packHsl(32, 4, 100);
		Model model = FakeModel.builder()
			.faceCount(1)
			.vertices(new float[]{0f, 1f, 0f}, new float[]{0f, 0f, 1f}, new float[]{0f, 0f, 0f})
			.faceIndices(new int[]{0}, new int[]{1}, new int[]{2})
			.faceColors(new int[]{hsl}, new int[]{hsl}, new int[]{hsl})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		assertEquals("one texture/translucency combination -> one primitive", 1, mesh.primitives.size());
		MeshData.Primitive primitive = mesh.primitives.get(0);
		assertEquals(-1, primitive.textureId);
		assertFalse(primitive.translucent);
		assertEquals("one triangle -> 3 indices", 3, primitive.indices.size());
		assertEquals("three distinct positions -> three distinct vertices, no accidental merging",
			3, mesh.positions.size());
		assertNull("no textured faces anywhere in this mesh -> no UV list at all", mesh.uvs);
	}

	@Test
	public void axisConversion_negatesYAndZ_leavesXAlone()
	{
		int hsl = packHsl(0, 0, 64);
		// Three genuinely distinct raw points on one triangle, chosen
		// so each axis's min AND max comes from a different vertex --
		// exercises the per-vertex sign flip and the running bounding
		// box together, with every value hand-checkable.
		Model model = FakeModel.builder()
			.faceCount(1)
			.vertices(new float[]{5f, -10f, 7f}, new float[]{2f, 9f, -4f}, new float[]{-1f, 3f, 8f})
			.faceIndices(new int[]{0}, new int[]{1}, new int[]{2})
			.faceColors(new int[]{hsl}, new int[]{hsl}, new int[]{hsl})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		// First vertex added is raw vertex 0: (5, 2, -1) -> (5, -2, 1).
		float[] p0 = mesh.positions.get(0);
		assertEquals("X unchanged", 5f, p0[0], EPS);
		assertEquals("Y negated (game Y-down -> glTF Y-up)", -2f, p0[1], EPS);
		assertEquals("Z negated", 1f, p0[2], EPS);

		// Converted points: (5,-2,1), (-10,-9,-3), (7,4,-8).
		assertEquals("min X", -10f, mesh.boundsMin[0], EPS);
		assertEquals("max X", 7f, mesh.boundsMax[0], EPS);
		assertEquals("min Y", -9f, mesh.boundsMin[1], EPS);
		assertEquals("max Y", 4f, mesh.boundsMax[1], EPS);
		assertEquals("min Z", -8f, mesh.boundsMin[2], EPS);
		assertEquals("max Z", 1f, mesh.boundsMax[2], EPS);
	}

	@Test
	public void sharedRawVertex_differentColorsPerFace_doesNotMerge()
	{
		// Two faces both reference raw model vertex 0, but each shades
		// it a different HSL color (a hard edge) -- these must stay two
		// separate glTF vertices, not collapse into a shared one that
		// would smear the two faces' colors together.
		int hslRed = packHsl(0, 7, 100);
		int hslBlue = packHsl(42, 7, 100);
		Model model = FakeModel.builder()
			.faceCount(2)
			.vertices(
				new float[]{0f, 1f, 0f, 2f},
				new float[]{0f, 0f, 1f, 0f},
				new float[]{0f, 0f, 0f, 1f})
			.faceIndices(new int[]{0, 0}, new int[]{1, 2}, new int[]{2, 3})
			.faceColors(
				new int[]{hslRed, hslBlue},
				new int[]{hslRed, hslBlue},
				new int[]{hslRed, hslBlue})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		// 2 faces x 3 corners = 6 corners total; raw vertex 0 is shared
		// but shaded two different colors by its two faces, raw
		// vertices 1/2 are each used once, raw vertex 3 once -- nothing
		// else repeats a (position, color) pair, so all 6 stay distinct.
		assertEquals(6, mesh.positions.size());
	}

	@Test
	public void identicalCorners_acrossDifferentFaces_doMerge()
	{
		// Two faces that share ONLY raw vertex 0 (and shade it the
		// exact same color there) -- every other corner is its own
		// distinct raw vertex, so exactly one of the six corners should
		// collapse into an existing glTF vertex, not the other five.
		int hsl = packHsl(10, 3, 90);
		Model model = FakeModel.builder()
			.faceCount(2)
			.vertices(
				new float[]{0f, 1f, 0f, 2f, 2f},
				new float[]{0f, 0f, 1f, 0f, 1f},
				new float[]{0f, 0f, 0f, 0f, 0f})
			.faceIndices(new int[]{0, 0}, new int[]{1, 3}, new int[]{2, 4})
			.faceColors(
				new int[]{hsl, hsl},
				new int[]{hsl, hsl},
				new int[]{hsl, hsl})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		// Corner (raw vertex 0, hsl) is identical between both faces ->
		// merges. 6 total corners minus that 1 merge = 5 distinct glTF
		// vertices (raw vertices 1, 2, 3, 4 each still their own).
		assertEquals(5, mesh.positions.size());
		// Both primitives' triangles should include the SAME index for
		// that shared corner.
		assertEquals(1, mesh.primitives.size());
		int firstFaceCornerA = mesh.primitives.get(0).indices.get(0);
		int secondFaceCornerA = mesh.primitives.get(0).indices.get(3);
		assertEquals("shared corner reused, not duplicated", firstFaceCornerA, secondFaceCornerA);
	}

	@Test
	public void fullyTransparentFace_isDropped()
	{
		int hsl = packHsl(0, 0, 64);
		Model model = FakeModel.builder()
			.faceCount(2)
			.vertices(new float[]{0f, 1f, 0f, 5f, 6f, 5f}, new float[]{0f, 0f, 1f, 5f, 5f, 6f}, new float[]{0f, 0f, 0f, 5f, 5f, 5f})
			.faceIndices(new int[]{0, 3}, new int[]{1, 4}, new int[]{2, 5})
			.faceColors(new int[]{hsl, hsl}, new int[]{hsl, hsl}, new int[]{hsl, hsl})
			.faceTransparencies(new byte[]{(byte) 255, 0})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		assertEquals("only the opaque face survives -> one primitive", 1, mesh.primitives.size());
		assertFalse(mesh.primitives.get(0).translucent);
		assertEquals("only the opaque face's 3 corners", 3, mesh.positions.size());
	}

	@Test
	public void hiddenFace_thirdColorIsSentinelMinus2_isExcludedEntirely()
	{
		// A third-corner color of -2 is a distinct sentinel from -1 (flat
		// shading, see the next test): it means the game never draws
		// this face at all. Reading it as a real color instead of
		// skipping the face is exactly the bug that put a stray
		// near-white triangle on top of a real fire cape capture -- this
		// checks the hidden face contributes NOTHING to the exported
		// mesh, not just that its color comes out muted.
		int hsl = packHsl(20, 5, 80);
		Model model = FakeModel.builder()
			.faceCount(2)
			.vertices(
				new float[]{0f, 1f, 0f, 5f, 6f, 5f},
				new float[]{0f, 0f, 1f, 5f, 5f, 6f},
				new float[]{0f, 0f, 0f, 5f, 5f, 5f})
			.faceIndices(new int[]{0, 3}, new int[]{1, 4}, new int[]{2, 5})
			.faceColors(new int[]{hsl, hsl}, new int[]{hsl, hsl}, new int[]{hsl, -2})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		assertEquals("the hidden face contributes nothing -- only the real face's primitive survives",
			1, mesh.primitives.size());
		assertEquals("only the real (non-hidden) face's 3 corners reached the vertex buffer",
			3, mesh.positions.size());
	}

	@Test
	public void flatShadedFace_thirdColorIsSentinelMinus1_usesCorner1ColorForAllThreeCorners()
	{
		// A third-corner color of -1 means flat shading: the whole face
		// is meant to use corner 1's own color, not a color per corner.
		// color2 here is deliberately different from color1 to prove it
		// gets overridden too (matching RuneProfile's own documented
		// handling: flat shading overrides corner 2 as well as the
		// sentinel corner 3, not only the -1 itself).
		int color1 = packHsl(10, 6, 90);
		int color2 = packHsl(40, 6, 30);
		Model model = FakeModel.builder()
			.faceCount(1)
			.vertices(new float[]{0f, 1f, 0f}, new float[]{0f, 0f, 1f}, new float[]{0f, 0f, 0f})
			.faceIndices(new int[]{0}, new int[]{1}, new int[]{2})
			.faceColors(new int[]{color1}, new int[]{color2}, new int[]{-1})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		float[] expected = HslColor.toLinearRgb(color1, HslColor.DEFAULT_BRIGHTNESS);
		assertEquals(3, mesh.colors.size());
		for (float[] rgb : mesh.colors)
		{
			assertEquals("every corner's RGB matches corner 1's own color, not its own raw c2/c3 value",
				expected[0], rgb[0], EPS);
			assertEquals(expected[1], rgb[1], EPS);
			assertEquals(expected[2], rgb[2], EPS);
		}
	}

	@Test
	public void partiallyTransparentFace_marksTranslucentPrimitive_withCorrectAlpha()
	{
		int hsl = packHsl(0, 0, 64);
		int transparency = 64; // out of 255
		Model model = FakeModel.builder()
			.faceCount(1)
			.vertices(new float[]{0f, 1f, 0f}, new float[]{0f, 0f, 1f}, new float[]{0f, 0f, 0f})
			.faceIndices(new int[]{0}, new int[]{1}, new int[]{2})
			.faceColors(new int[]{hsl}, new int[]{hsl}, new int[]{hsl})
			.faceTransparencies(new byte[]{(byte) transparency})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		assertTrue(mesh.primitives.get(0).translucent);
		float expectedAlpha = 1f - (transparency / 255f);
		assertEquals(expectedAlpha, mesh.colors.get(0)[3], EPS);
	}

	@Test
	public void texturedFace_splitsIntoOwnPrimitive_andComputesAxisAlignedUv()
	{
		// Reference triangle: origin (0,0,0), U axis end (1,0,0), V
		// axis end (0,1,0) -- an orthonormal, axis-aligned basis, so
		// each face vertex's UV should equal its own (x, y) coordinate
		// exactly, hand-checkable without needing the general
		// projection math to be re-derived here.
		//
		// Model vertices: 0/1/2 are the reference triangle itself;
		// 3/4/5 are the actual rendered face, at (0.5,0.3,0),
		// (1,1,0), (0,0.5,0) -- all in the same z=0 plane as the
		// reference triangle so the projection is exact, not just a
		// least-squares approximation.
		short textureId = 42;
		int litHsl = 127; // textured-face "color" is a pure lightness multiplier -- see HslColor.
		Model model = FakeModel.builder()
			.faceCount(1)
			.vertices(
				new float[]{0f, 1f, 0f, 0.5f, 1f, 0f},
				new float[]{0f, 0f, 1f, 0.3f, 1f, 0.5f},
				new float[]{0f, 0f, 0f, 0f, 0f, 0f})
			.faceIndices(new int[]{3}, new int[]{4}, new int[]{5})
			.faceColors(new int[]{litHsl}, new int[]{litHsl}, new int[]{litHsl})
			.faceTextures(new short[]{textureId})
			.textureTriangles(new byte[]{0}, new int[]{0}, new int[]{1}, new int[]{2})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		assertEquals(1, mesh.primitives.size());
		assertEquals(textureId, mesh.primitives.get(0).textureId);
		assertNull("bare int, no need for the sign/width dance -- textureId already unsigned", null);

		assertEquals("mesh has a textured face -> UV list exists", 3, mesh.uvs.size());
		assertUv(mesh.uvs.get(0), 0.5f, 0.3f);
		assertUv(mesh.uvs.get(1), 1f, 1f);
		assertUv(mesh.uvs.get(2), 0f, 0.5f);

		// A fully-lit (127) textured face's color should come out as
		// white, per HslColor's own documented behavior for this case.
		for (float[] color : mesh.colors)
		{
			assertEquals(1f, color[0], EPS);
			assertEquals(1f, color[1], EPS);
			assertEquals(1f, color[2], EPS);
		}
	}

	@Test
	public void untexturedAndTexturedFaces_inSameMesh_splitIntoTwoPrimitives()
	{
		int plainHsl = packHsl(20, 5, 80);
		short textureId = 7;
		Model model = FakeModel.builder()
			.faceCount(2)
			.vertices(
				new float[]{0f, 1f, 0f, 10f, 11f, 10f},
				new float[]{0f, 0f, 1f, 10f, 10f, 11f},
				new float[]{0f, 0f, 0f, 10f, 10f, 10f})
			.faceIndices(new int[]{0, 3}, new int[]{1, 4}, new int[]{2, 5})
			.faceColors(
				new int[]{plainHsl, 100},
				new int[]{plainHsl, 100},
				new int[]{plainHsl, 100})
			// -1 for the untextured face's own faceTextures entry, a
			// real id for the textured one -- exactly how a real mixed
			// model marks "this particular face has no texture" per
			// this class's own doc.
			.faceTextures(new short[]{-1, textureId})
			.textureTriangles(new byte[]{0, 1}, new int[]{0, 3}, new int[]{1, 4}, new int[]{2, 5})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		assertEquals(2, mesh.primitives.size());
		boolean sawUntextured = false;
		boolean sawTextured = false;
		for (MeshData.Primitive p : mesh.primitives)
		{
			if (p.textureId == -1)
			{
				sawUntextured = true;
			}
			if (p.textureId == textureId)
			{
				sawTextured = true;
			}
		}
		assertTrue(sawUntextured);
		assertTrue(sawTextured);
		// UV list must exist (mesh has at least one textured face) and
		// have an entry for every vertex including the untextured
		// face's own three, per MeshData's own documented contract.
		assertEquals(mesh.positions.size(), mesh.uvs.size());
	}

	@Test
	public void differentRenderPriorityOrBias_splitsIntoSeparatePrimitives_evenWithSameTextureAndTranslucency()
	{
		// Three faces, all untextured and opaque (so textureId/translucent
		// alone would put them in ONE primitive under the old key) but
		// with three different (priority, bias) combinations -- the whole
		// point of folding priority/bias into the primitive key is that
		// these must come out as three separate primitives, each able to
		// carry its own draw-order extras.
		int hsl = packHsl(0, 0, 64);
		Model model = FakeModel.builder()
			.faceCount(3)
			.vertices(
				new float[]{0f, 1f, 0f, 5f, 6f, 5f, 10f, 11f, 10f},
				new float[]{0f, 0f, 1f, 5f, 5f, 6f, 10f, 10f, 11f},
				new float[]{0f, 0f, 0f, 5f, 5f, 5f, 10f, 10f, 10f})
			.faceIndices(new int[]{0, 3, 6}, new int[]{1, 4, 7}, new int[]{2, 5, 8})
			.faceColors(
				new int[]{hsl, hsl, hsl},
				new int[]{hsl, hsl, hsl},
				new int[]{hsl, hsl, hsl})
			.faceRenderPriorities(new byte[]{0, 5, 5})
			.faceBias(new byte[]{0, 0, 9})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		assertEquals("three distinct (priority, bias) pairs -> three primitives", 3, mesh.primitives.size());
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (MeshData.Primitive p : mesh.primitives)
		{
			seen.add(p.priority + "," + p.bias);
		}
		assertTrue(seen.contains("0,0"));
		assertTrue(seen.contains("5,0"));
		assertTrue(seen.contains("5,9"));
	}

	@Test
	public void nullRenderPriorityAndBiasArrays_defaultToZero()
	{
		// A model that never calls faceRenderPriorities()/faceBias() at
		// all (FakeModel's own default) must behave exactly as it did
		// before priority/bias existed -- one primitive, priority 0.
		int hsl = packHsl(0, 0, 64);
		Model model = FakeModel.builder()
			.faceCount(1)
			.vertices(new float[]{0f, 1f, 0f}, new float[]{0f, 0f, 1f}, new float[]{0f, 0f, 0f})
			.faceIndices(new int[]{0}, new int[]{1}, new int[]{2})
			.faceColors(new int[]{hsl}, new int[]{hsl}, new int[]{hsl})
			.build();

		MeshData mesh = ModelMeshBuilder.build(model, HslColor.DEFAULT_BRIGHTNESS);

		assertEquals(1, mesh.primitives.size());
		assertEquals(0, mesh.primitives.get(0).priority);
		assertEquals(0, mesh.primitives.get(0).bias);
	}

	private static void assertUv(float[] uv, float expectedU, float expectedV)
	{
		assertEquals(expectedU, uv[0], EPS);
		assertEquals(expectedV, uv[1], EPS);
	}

	/** Packs (hue 0..63, sat 0..7, lightness 0..127) into OSRS's own
	 * 16-bit format -- see HslColor's own doc for the bit layout,
	 * confirmed against RuneLite's real hsl_to_rgb.glsl. */
	private static int packHsl(int hue, int sat, int lightness)
	{
		return (hue << 10) | (sat << 7) | lightness;
	}
}

package io.myscape.plugin.modelexport;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.Collections;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.imageio.ImageIO;
import net.runelite.api.Texture;
import net.runelite.api.TextureProvider;
import org.junit.Test;
import org.mockito.InOrder;
import org.mockito.Mockito;

/**
 * Checks {@link TextureExtractor} against a mocked {@code
 * TextureProvider} -- this environment has no live game client, so a
 * mock (matching this codebase's existing FakeModel approach for
 * {@code Model} itself, just via Mockito here since {@code
 * TextureProvider} is a small interface with no long tail of unrelated
 * methods to stub around) is the only way to exercise this class's own
 * logic at all. Decodes the PNG bytes it produces back out with the
 * JDK's own {@code ImageIO} -- reading the actual encoded image, not
 * just trusting the code that wrote it -- to confirm both the pixel
 * values and the zero-means-transparent convention documented on
 * TextureExtractor itself.
 */
public class TextureExtractorTest
{
	private static final int SIZE = 128;

	@Test
	public void extractsRealPixelsAndEncodesThemAsPng() throws IOException
	{
		int[] pixels = new int[SIZE * SIZE];
		// A simple recognizable pattern: top-left quadrant red, rest a
		// mid-gray -- enough to catch a row/column transposition bug in
		// the (x, y) loop, which a uniform fill wouldn't.
		for (int y = 0; y < SIZE; y++)
		{
			for (int x = 0; x < SIZE; x++)
			{
				pixels[y * SIZE + x] = (x < SIZE / 2 && y < SIZE / 2) ? 0xFF0000 : 0x404040;
			}
		}

		TextureProvider provider = mockProviderWithTexture(7, pixels);

		Map<Integer, byte[]> result = TextureExtractor.extractPngs(provider, setOf(7));

		assertTrue("texture 7 was extracted", result.containsKey(7));
		BufferedImage decoded = ImageIO.read(new ByteArrayInputStream(result.get(7)));
		assertEquals(SIZE, decoded.getWidth());
		assertEquals(SIZE, decoded.getHeight());
		assertEquals("red quadrant round-trips, opaque", 0xFFFF0000, decoded.getRGB(10, 10));
		assertEquals("gray region round-trips, opaque", 0xFF404040, decoded.getRGB(100, 100));
	}

	@Test
	public void zeroPixelValueDecodesAsTransparentNotBlack()
	{
		int[] pixels = new int[SIZE * SIZE];
		pixels[0] = 0x000000; // the format's own "no data" marker, not literal black
		pixels[1] = 0xFFFFFF; // a real (opaque) white pixel, for contrast

		TextureProvider provider = mockProviderWithTexture(2, pixels);

		Map<Integer, byte[]> result = TextureExtractor.extractPngs(provider, setOf(2));

		BufferedImage decoded = decode(result.get(2));
		assertEquals("packed 0 -> fully transparent, alpha channel zeroed", 0x00000000, decoded.getRGB(0, 0));
		assertEquals("a real white pixel stays opaque white", 0xFFFFFFFF, decoded.getRGB(1, 0));
	}

	@Test
	public void pinsBrightnessToOneForTheDurationOfExtractionThenRestoresIt()
	{
		TextureProvider provider = mockProviderWithTexture(1, new int[SIZE * SIZE]);
		when(provider.getBrightness()).thenReturn(0.8d);

		TextureExtractor.extractPngs(provider, setOf(1));

		// See TextureExtractor's own top-of-file doc: TextureProvider
		// bakes its own current brightness into load()'s pixels, and
		// this package already applies brightness separately per-vertex
		// (HslColor#textureLightnessToRgb), so extraction must happen at
		// 1.0 and the player's real setting must come back afterward.
		InOrder order = Mockito.inOrder(provider);
		order.verify(provider).getBrightness();
		order.verify(provider).setBrightness(1.0d);
		order.verify(provider).load(1);
		order.verify(provider).setBrightness(0.8d);
	}

	@Test
	public void restoresBrightnessEvenIfATextureThrowsMidBatch()
	{
		TextureProvider provider = mock(TextureProvider.class);
		when(provider.getBrightness()).thenReturn(0.8d);
		Texture[] textures = new Texture[]{mock(Texture.class), mock(Texture.class)};
		when(provider.getTextures()).thenReturn(textures);
		when(provider.load(0)).thenThrow(new RuntimeException("boom"));

		try
		{
			TextureExtractor.extractPngs(provider, setOf(0));
			org.junit.Assert.fail("expected the mocked load() failure to propagate");
		}
		catch (RuntimeException expected)
		{
			// expected -- extraction doesn't swallow a genuinely
			// unexpected RuntimeException from the provider itself
			// (unlike the documented, expected-in-practice cases --
			// missing texture, wrong-sized array -- which are handled
			// by returning null, not throwing); what this test actually
			// checks is the finally block below, not this exception.
		}

		// The whole point of the try/finally bracket: even though
		// load(0) blew up mid-batch, the player's real brightness
		// setting must still come back, not stay pinned at 1.0.
		verify(provider).setBrightness(0.8d);
	}

	@Test
	public void unknownOrOutOfRangeTextureIdIsSkippedNotFailed()
	{
		TextureProvider provider = mock(TextureProvider.class);
		when(provider.getTextures()).thenReturn(new Texture[]{null, mock(Texture.class)});

		Map<Integer, byte[]> result = TextureExtractor.extractPngs(provider, setOf(0, 1, 99, -1));

		assertTrue("id 0 has a null Texture entry -> skipped", !result.containsKey(0));
		assertTrue("id 99 is out of bounds -> skipped", !result.containsKey(99));
		assertTrue("id -1 is never a real texture id -> skipped", !result.containsKey(-1));
		// id 1 has a non-null Texture but load() isn't stubbed (returns
		// null by default), so it's skipped too -- nothing should be in
		// the result map at all here.
		assertTrue(result.isEmpty());
	}

	@Test
	public void wrongSizedPixelArrayIsSkipped()
	{
		TextureProvider provider = mock(TextureProvider.class);
		when(provider.getTextures()).thenReturn(new Texture[]{mock(Texture.class)});
		when(provider.load(0)).thenReturn(new int[]{1, 2, 3}); // not 128*128

		Map<Integer, byte[]> result = TextureExtractor.extractPngs(provider, setOf(0));

		assertTrue(result.isEmpty());
	}

	@Test
	public void nullProviderReturnsEmptyMapRatherThanThrowing()
	{
		assertTrue(TextureExtractor.extractPngs(null, setOf(1)).isEmpty());
	}

	@Test
	public void emptyRequestedIdsSkipsProviderEntirely()
	{
		TextureProvider provider = mock(TextureProvider.class);

		Map<Integer, byte[]> result = TextureExtractor.extractPngs(provider, Collections.emptySet());

		assertTrue(result.isEmpty());
		verify(provider, times(0)).getTextures();
	}

	private static TextureProvider mockProviderWithTexture(int id, int[] pixels)
	{
		TextureProvider provider = mock(TextureProvider.class);
		Texture[] textures = new Texture[id + 1];
		textures[id] = mock(Texture.class);
		when(provider.getTextures()).thenReturn(textures);
		when(provider.load(id)).thenReturn(pixels);
		return provider;
	}

	private static BufferedImage decode(byte[] png)
	{
		try
		{
			return ImageIO.read(new ByteArrayInputStream(png));
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
	}

	private static Set<Integer> setOf(int... ids)
	{
		Set<Integer> set = new HashSet<>();
		for (int id : ids)
		{
			set.add(id);
		}
		return set;
	}
}
